function analytics(){return `${heading('EVENT INSIGHTS','Analytics','A clear picture of judging speed, score patterns, and submission quality.','<button class="btn" data-action="export">⇩ Export report</button>')}<section class="stats">${[['Median review time','8.4 min','↓ 32% from manual baseline'],['AI score acceptance','82%','Accepted or changed by under 2 points'],['Submission completeness','88%','21 of 24 teams complete'],['Judge agreement','91%','Average criterion agreement']].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div></div>`).join('')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Evaluations over time</h3><p>Completed reviews · This week</p></div><span class="status">16 completed</span></div><div class="mini-bars">${[18,38,31,54,71,62,85].map((n,i)=>`<div class="bar-col"><div class="bar ${i===6?'primary':''}" style="height:${n}%"><small>${'MTWTFSS'[i]}</small></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>Score distribution</h3><p>Current AI recommendations</p></div></div><div class="score-distribution"><div class="donut"></div><div class="legend"><div>● Strong · 43%</div><div>● Promising · 29%</div><div>● Developing · 17%</div><div>● Early stage · 11%</div></div></div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Organizer impact</h3><p>Northstar Innovation Sprint · Round 1</p></div></div><div class="dashboard-grid"><div><div class="eyebrow">TIME SAVED ESTIMATE</div><div class="stat-value">9.6 hours</div><p class="muted">Across 16 completed project reviews</p></div><div><div class="eyebrow">TOP INTEGRITY CHECKS</div><div class="event-row"><span>⚠</span><div class="event-info"><b>3 projects need attention</b><small>2 missing documents · 1 unavailable live link</small></div></div></div></div></section>`}
function settingsPage(){return `${heading('WORKSPACE SETTINGS','Settings','Manage your event preferences, review rules, and participant communications.','<button class="btn btn-primary" data-action="save-settings">Save changes</button>')}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Review and publishing</h3><p>Northstar Innovation Sprint</p></div></div><div class="form-field"><label>Result publication</label><select class="select" style="width:100%"><option>Organizer publishes after judge approval</option><option>Publish automatically after all reviews</option></select></div><div class="form-field"><label>Low confidence threshold</label><select class="select" style="width:100%"><option>Flag scores below 70% confidence</option><option>Flag scores below 60% confidence</option></select></div><div class="form-field"><label>Participant review window</label><select class="select" style="width:100%"><option>7 days after results are published</option><option>14 days after results are published</option></select></div>${['Require evidence for every criterion','Require judge approval before publishing'].map(t=>`<div class="event-row"><div class="event-info"><b>${t}</b><small>Enforced in the JudgeX workflow.</small></div><input type="checkbox" checked></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h3>Participant notifications</h3><p>Feedback and event emails</p></div></div>${['Registration confirmation','Submission received','Incomplete submission reminder','Result and feedback report'].map(t=>`<div class="event-row"><div class="event-info"><b>${t}</b><small>Prototype email workflow</small></div><input type="checkbox" checked></div>`).join('')}<p class="muted" style="font-size:9px;line-height:1.6">Email delivery needs a connected provider. Changes here are stored only in the prototype.</p></section></div>`}
function render(){if(apiReady&&['judging','leaderboard','analytics'].includes(page)){$('#app').innerHTML=`${heading('PHASE 1 COMPLETE','Evaluation services come next','This workspace is connected to your Phase 1 event and submission data. AI scorecards, human review decisions, and published results will be connected in later build phases.')}<section class="panel"><div class="panel-head"><div><h3>What is available now</h3><p>Event setup, team registration, project submissions, document storage, and repository or deployment link checks.</p></div><span class="status">Phase 1</span></div><div class="event-row"><span class="activity-icon">✓</span><div class="event-info"><b>Real accounts and role checks</b><small>Accounts are stored in the local database; organizers and participants have separate permissions.</small></div></div><div class="event-row"><span class="activity-icon">✓</span><div class="event-info"><b>Persistent event and submission data</b><small>Events, teams, submissions, and uploaded documents are saved by the API.</small></div></div><div class="event-row"><span class="activity-icon">→</span><div class="event-info"><b>Next phase: AI Pitch Room</b><small>Pitch upload, speech-to-text, evidence extraction, and scorecard generation.</small></div></div></section>`;return}let fn=({overview,events:eventsPage,submissions:submissionsPage,participant:participantPage,judging:judgingPage,leaderboard,rubric:rubricPage,analytics,settings:settingsPage})[page]||overview;$('#app').innerHTML=fn();if(page==='participant'&&apiReady){const area=$('#app .pitch-layout>aside'),form=$('#app .pitch-layout>div .panel');if(area&&form){const active=submissions.find(s=>teams.some(t=>t.id===s.team_id))||null;const teamOptions=teams.map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(events.find(ev=>ev.id===t.hackathon_id)?.name||'Hackathon')}</option>`).join('');const teamPanel=`<section class="panel" style="margin-bottom:14px"><div class="panel-head"><div><h3>Your team</h3><p>Create a team or join with an invite code.</p></div></div>${teams.map(t=>`<div class="event-row"><div class="event-logo">${esc(t.name[0])}</div><div class="event-info"><b>${esc(t.name)}</b><small>Invite code · ${esc(t.join_code)}</small></div></div>`).join('')||'<p class="pitch-note">You have not joined a team yet.</p>'}<div class="form-field"><label>Open hackathon</label><select id="team-event" class="select" style="width:100%"><option value="">Choose an event</option>${events.filter(e=>['Registration open','Live'].includes(e.status)).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="form-grid"><input id="new-team-name" placeholder="New team name"><button class="btn btn-sm" data-action="create-team">Create team</button></div><div class="form-grid" style="margin-top:9px"><input id="team-join-code" placeholder="Invite code"><button class="btn btn-sm" data-action="join-team">Join team</button></div></section>`;area.insertAdjacentHTML('afterbegin',teamPanel);const field=form.querySelector('.form-grid');if(field){field.insertAdjacentHTML('beforebegin',`<div class="form-field"><label>Your team</label><select id="participant-team" class="select" style="width:100%"><option value="">Choose a team before saving</option>${teamOptions}</select></div>`);const select=$('#participant-team');if(select)select.value=active?.team_id||teams[0]?.id||''}const bind={"Project title":"participant-title","Team name":"participant-team-name","Problem statement":"participant-problem","Solution summary":"participant-summary","GitHub repository":"participant-repo","Live deployment":"participant-live"};form.querySelectorAll('.form-field').forEach(box=>{const label=box.querySelector('label')?.textContent?.trim(),id=bind[label];if(id){const input=box.querySelector('input,textarea');if(input){input.id=id;const data=active?.[{"Project title":"title","Problem statement":"problem_statement","Solution summary":"solution_summary","GitHub repository":"repo","Live deployment":"live_url","Team name":"team"}[label]];input.value=data||''}}});const beforeRepo=[...form.querySelectorAll('.form-field')].find(x=>x.querySelector('label')?.textContent?.trim()==='GitHub repository');if(beforeRepo){const event=events.find(x=>x.id===teams.find(t=>t.id===$('#participant-team')?.value)?.hackathon_id);beforeRepo.insertAdjacentHTML('beforebegin',`<div class="form-field"><label>Track</label><select id="participant-track" class="select" style="width:100%"><option value="">Choose a track</option>${(event?.trackData||[]).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div>`);$('#participant-track').value=active?.track_id||''}const pitch=[...area.querySelectorAll('.panel')].find(x=>x.innerText.includes('Pitch guidance'));const docs=`<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Project documents</h3><p>Upload a PRD, architecture image, slides, or demo backup.</p></div></div><div class="form-field"><label>Document type</label><select id="document-kind" class="select" style="width:100%"><option value="prd">Project PRD</option><option value="architecture">Architecture diagram</option><option value="slides">Presentation slides</option><option value="screenshot">Screenshot</option><option value="demo_video">Demo video</option><option value="other">Other documentation</option></select></div><input type="file" id="participant-file" accept=".pdf,.docx,.pptx,.png,.jpg,.jpeg,.webp,.txt,.md,.mp4,.webm"><button class="btn" style="margin-top:10px;width:100%" data-action="upload-document">Upload selected file</button><p class="pitch-note">Private storage · maximum 25 MB per file.</p></section>`;pitch?.insertAdjacentHTML('beforebegin',docs)}}}
function syncLiveDataView(){if(!apiReady)return;const organizer=['organizer','super_admin'].includes(currentUser?.role),participant=currentUser?.role==='participant';$$('.nav-item[data-page="analytics"],.nav-item[data-page="rubric"],.nav-item[data-page="settings"]').forEach(x=>x.style.display=organizer?'':'none');$$('.nav-item[data-page="participant"]').forEach(x=>x.style.display=participant?'':'none');$$('.nav-item[data-page="leaderboard"]').forEach(x=>x.style.display=organizer?'':'none');$$('[data-action="new-event"]').forEach(x=>x.style.display=organizer?'':'none');$$('[data-action="new-submission"]').forEach(x=>x.style.display=participant?'':'none');const subCount=$('.nav-item[data-page="submissions"] i');if(subCount)subCount.textContent=String(submissions.length);const judgeCount=$('.nav-item[data-page="judging"] i');if(judgeCount)judgeCount.remove();if(page==='overview'){const title=$('#app .hero h2');if(title)title.textContent=events[0]?.name||'Create your first hackathon';const deck=$$('#app .stats .stat-card');const submitted=submissions.filter(s=>s.status==='Ready for review'||s.status==='Approved').length,drafts=submissions.filter(s=>s.status==='Draft').length,flags=submissions.filter(s=>s.status==='Needs attention').length;const values=[submissions.length,submitted,drafts,flags],labels=['Stored submissions','Submitted for review','Draft projects','Link issues'],foots=['Saved by the JudgeX API','Human judging is part of a later phase','Finish and submit project details','Repository or deployment checks need attention'];deck.forEach((card,i)=>{if(!card)return;card.querySelector('.stat-top').childNodes[0].textContent=labels[i]+' ';card.querySelector('.stat-value').textContent=values[i];card.querySelector('.stat-foot').textContent=foots[i]});const activity=$$('#app .dashboard-grid')[0]?.children[1];if(activity)activity.innerHTML='<div class="panel-head"><div><h3>Workspace activity</h3><p>Recent changes from your account</p></div></div><div class="activity-item"><span class="activity-icon">✓</span><div><p><b>API connected</b> Events, teams, and submissions now use your local database.</p><small>Current session</small></div></div><div class="activity-item"><span class="activity-icon">→</span><div><p><b>Judging is next</b> AI evaluations and human scorecards are not connected in Phase 1.</p><small>Upcoming phase</small></div></div>';const charts=$$('#app .bottom-grid')[0];if(charts)charts.style.display='none'}if(page==='submissions'){const cards=$$('#app .stats .stat-card'),all=submissions.length,complete=submissions.filter(s=>s.status==='Ready for review'||s.status==='Approved').length,attention=submissions.filter(s=>s.status==='Needs attention').length,drafts=submissions.filter(s=>s.status==='Draft').length;[[all,'Saved submissions','From your API database'],[complete,'Submitted','Ready for later judging'],[attention,'Need attention','Broken or missing links'],[drafts,'Drafts','Not yet submitted']].forEach((x,i)=>{if(cards[i]){cards[i].querySelector('.stat-top').childNodes[0].textContent=x[1]+' ';cards[i].querySelector('.stat-value').textContent=x[0];cards[i].querySelector('.stat-foot').textContent=x[2]}})}if(page==='participant'){const selected=$('#participant-team')?.value,team=teams.find(t=>t.id===selected),sub=submissions.find(s=>s.team_id===selected),desc=$$('#app .page-heading p')[0];if(desc)desc.textContent=`${sub?.title||'New project'} · ${team?.name||'Join or create a team'} · ${events.find(x=>x.id===team?.hackathon_id)?.name||'Choose an open hackathon'}`;const checklist=$('#app .pitch-layout>aside .checklist');if(checklist){const items=[['Project details',Boolean(sub?.title&&sub.problem_statement&&sub.solution_summary)],['GitHub repository',Boolean(sub?.repo)],['Live deployment link',Boolean(sub?.live_url)],['Project PRD',Boolean(sub?.documents?.some(d=>d.kind==='prd'))],['Architecture diagram',Boolean(sub?.documents?.some(d=>d.kind==='architecture'))],['Pitch recording',false],['Team member details',Boolean(team?.members?.length)]];const done=items.filter(x=>x[1]).length;checklist.innerHTML=items.map(([label,ok])=>`<div class="check-row"><span class="checkmark ${ok?'':'missing'}">${ok?'✓':'○'}</span><div><b>${label}</b><small>${ok?'Received or detected':label==='Pitch recording'?'Local capture is available in this browser':'Still needed'}</small></div></div>`).join('');const head=checklist.closest('.panel')?.querySelector('.panel-head');if(head){head.querySelector('p').textContent=`${done} of ${items.length} items complete`;head.querySelector('.status').textContent=`${items.length-done} to go`}}}}
