syncLiveDataView=function(){phaseOneSync();if(!apiReady||page!=='participant')return;const form=$('#app .pitch-layout>div .panel');if(!form)return;const repo=[...form.querySelectorAll('.form-field')].find(x=>x.querySelector('label')?.textContent?.trim()==='GitHub repository');if(repo&&!$('#participant-tech-stack'))repo.insertAdjacentHTML('beforebegin','<div class="form-grid"><div class="form-field"><label>Target users</label><input id="participant-target-users" placeholder="Who will use the project?"></div><div class="form-field"><label>Tech stack</label><input id="participant-tech-stack" placeholder="Languages, frameworks, services"></div></div>');const teamId=$('#participant-team')?.value,active=submissions.find(s=>s.team_id===teamId);if($('#participant-target-users'))$('#participant-target-users').value=active?.target_users||'';if($('#participant-tech-stack'))$('#participant-tech-stack').value=active?.tech_stack||''};
function exportCsv(){let data=[['ID','Project','Team','Track','Status','Score','Judge approved'],...submissions.map(s=>[s.id,s.title,s.team,s.track,s.status,s.score,s.reviewed?'Yes':'No'])];let csv=data.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='judgex-northstar-results.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV report downloaded')}
function weights(){let total=0;$$('[data-weight]').forEach(x=>{let v=Math.max(0,Math.min(100,Number(x.value)||0));rubric[+x.dataset.weight].weight=v;total+=v});let el=$('#weight-total');if(el){el.textContent=`Total weight: ${total}% ${total===100?'✓':'⚠'}`;el.style.color=total===100?'#418164':'#b47b3a'}}
function closeModal(){ $('#modal-backdrop').classList.remove('open') }
function createEvent(){modal('Create a hackathon',`<div class="form-field"><label>Hackathon title</label><input id="event-name" placeholder="e.g. Northstar Winter Build"></div><div class="form-grid"><div class="form-field"><label>Start date</label><input id="event-start" type="date"></div><div class="form-field"><label>End date</label><input id="event-end" type="date"></div></div><div class="form-grid"><div class="form-field"><label>First track</label><input id="event-track" placeholder="Open Innovation"></div><div class="form-field"><label>Team limit</label><input id="event-limit" type="number" value="30" min="1"></div></div><div class="form-field"><label>Event description</label><textarea placeholder="What will teams build?"></textarea></div>`,'Create event',()=>{let name=$('#event-name').value.trim();if(!name){toast('Add a hackathon title to continue');return}events.unshift({name,category:($('#event-track').value||'Open Innovation')+' · Registration',date:$('#event-start').value||'Dates to be confirmed',teams:0,reviewed:0,status:'Draft',initials:name[0].toUpperCase()});save();closeModal();render();toast('Hackathon created as a draft')})}
function createSubmission(){modal('Add a project submission',`<div class="form-grid"><div class="form-field"><label>Project title</label><input id="proj-title" placeholder="Project name"></div><div class="form-field"><label>Team name</label><input id="team-name" placeholder="Team name"></div></div><div class="form-field"><label>Track</label><select id="proj-track" class="select" style="width:100%"><option>AI / Machine Learning</option><option>Web & Mobile</option><option>HealthTech</option><option>FinTech</option><option>Sustainability</option><option>Open Innovation</option></select></div><div class="form-field"><label>GitHub repository URL</label><input id="proj-repo" placeholder="https://github.com/team/project"></div><p class="muted" style="font-size:9px">Stored in this browser. Repository checks need a connected GitHub integration.</p>`,'Add submission',()=>{let title=$('#proj-title').value.trim(),team=$('#team-name').value.trim();if(!title||!team){toast('Project and team names are required');return}submissions.unshift({id:'JX-'+String(25+submissions.length-seed.length).padStart(3,'0'),title,team,track:$('#proj-track').value,status:'Ready for review',score:0,initials:team.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),reviewed:false});save();closeModal();go('submissions');toast('Submission added to the review queue')})}
function approve(){let s=submissions.find(x=>x.id===activeId)||submissions.find(x=>!x.reviewed);if(!s){toast('No submission selected');return}let sum=rubric.reduce((a,c)=>a+c.weight,0);s.score=Math.round(rubric.reduce((a,c)=>a+c.score*c.weight,0)/(sum||1)*10);s.reviewed=true;s.status='Approved';save();let i=events.findIndex(x=>x.status==='Live');if(i>=0)events[i].reviewed=Math.min(events[i].teams,events[i].reviewed+1);save();go('judging');toast(`Human-approved score saved for ${s.title} · ${s.score}/100`)}
async function startPitch(){if(!$('#record-consent')?.checked){toast('Consent is required before recording');return}if(!navigator.mediaDevices?.getUserMedia){toast('Camera and microphone capture need a secure browser context');return}try{mediaStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});let video=$('#camera-preview');video.srcObject=mediaStream;video.style.display='block';$('#camera-placeholder').style.display='none';recordChunks=[];let mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm';recorder=new MediaRecorder(mediaStream,{mimeType:mime});recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onstop=()=>{if(recordChunks.length){let blob=new Blob(recordChunks,{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='judgex-pitch-'+new Date().toISOString().slice(0,10)+'.webm';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Pitch recording downloaded to this device')}mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;video.srcObject=null;video.style.display='none';$('#camera-placeholder').style.display='block';$('#record-pill').style.display='none';$('#pitch-status').textContent='Recording saved';$('#pitch-status').className='status';$$('[data-action="pitch-start"],[data-action="pitch-screen"],[data-action="pitch-stop"]').forEach(b=>b.disabled=b.dataset.action!=='pitch-start')};recorder.start(1000);pitchSeconds=0;$('#pitch-status').textContent='Recording';$('#pitch-status').className='status review';$('#record-pill').style.display='inline-block';$$('[data-action="pitch-start"],[data-action="pitch-screen"],[data-action="pitch-stop"]').forEach(b=>b.disabled=b.dataset.action!=='pitch-screen'&&b.dataset.action!=='pitch-stop');pitchInterval=setInterval(()=>{pitchSeconds++;let m=String(Math.floor(pitchSeconds/60)).padStart(2,'0'),s=String(pitchSeconds%60).padStart(2,'0');let clock=$('#pitch-duration');if(clock)clock.textContent=m+':'+s},1000)}catch(err){toast(err.name==='NotAllowedError'?'Camera or microphone permission was not granted':'Could not start pitch capture. Check your camera and microphone.')}}
async function sharePitchScreen(){if(!$('#record-consent')?.checked){toast('Consent is required before recording');return}try{let display=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false}),track=display.getVideoTracks()[0];mediaStream.getVideoTracks().forEach(t=>mediaStream.removeTrack(t));mediaStream.addTrack(track);$('#camera-preview').srcObject=display;track.onended=()=>toast('Screen sharing stopped; stop or restart the recording')}catch(err){toast('Screen sharing was cancelled or unavailable')}}
function stopPitch(){if(pitchInterval){clearInterval(pitchInterval);pitchInterval=null}if(recorder&&recorder.state!=='inactive')recorder.stop();else toast('There is no active recording')}
function createEvent(){modal('Create a hackathon',`<div class="form-field"><label>Hackathon title</label><input id="event-name" placeholder="e.g. Northstar Winter Build" required></div><div class="form-grid"><div class="form-field"><label>Start date</label><input id="event-start" type="date"></div><div class="form-field"><label>End date</label><input id="event-end" type="date"></div></div><div class="form-grid"><div class="form-field"><label>First track</label><input id="event-track" placeholder="Open Innovation"></div><div class="form-field"><label>Team limit</label><input id="event-limit" type="number" value="30" min="1"></div></div><div class="form-field"><label>Event description</label><textarea id="event-desc" placeholder="What will teams build?"></textarea></div>`,'Create event',async()=>{const title=$('#event-name').value.trim();if(!title){toast('Add a hackathon title to continue');return}try{await api('/hackathons',{method:'POST',body:{title,description:$('#event-desc').value.trim(),start_date:$('#event-start').value?new Date($('#event-start').value+'T00:00:00Z').toISOString():null,end_date:$('#event-end').value?new Date($('#event-end').value+'T00:00:00Z').toISOString():null,team_size_min:1,team_size_max:Number($('#event-limit').value)||4,pitch_duration_minutes:5,tracks:$('#event-track').value.trim()?[{name:$('#event-track').value.trim()}]:[]}});closeModal();await enterWorkspace();go('events');toast('Hackathon created as a draft')}catch(err){toast(err.message)}})}
function createSubmission(){if(!teams.length){toast('Create or join a team in Participant portal first');go('participant');return}const trackOptions=events.flatMap(e=>(e.trackData||[]).map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(e.name)}</option>`)).join('');modal('Add a project submission',`<div class="form-field"><label>Team</label><select id="submission-team" class="select" style="width:100%">${teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="form-field"><label>Project title</label><input id="proj-title" placeholder="Project name"></div><div class="form-field"><label>Track</label><select id="proj-track" class="select" style="width:100%"><option value="">Choose a track</option>${trackOptions}</select></div></div><div class="form-field"><label>Problem statement</label><textarea id="proj-problem" placeholder="Who has which problem?"></textarea></div><div class="form-field"><label>Solution summary</label><textarea id="proj-summary" placeholder="How does your project help?"></textarea></div><div class="form-grid"><div class="form-field"><label>GitHub repository</label><input id="proj-repo" placeholder="https://github.com/team/project"></div><div class="form-field"><label>Live deployment</label><input id="proj-live" placeholder="https://example.com"></div></div><div class="form-field"><label>Attach PRD (optional, max 25 MB)</label><input id="proj-file" type="file" accept=".pdf,.docx,.pptx,.png,.jpg,.jpeg,.webp,.txt,.md"></div>`,'Save draft',async()=>{const title=$('#proj-title').value.trim(),team_id=$('#submission-team').value;if(!title){toast('Project title is required');return}try{const created=await api('/submissions',{method:'POST',body:{team_id,track_id:$('#proj-track').value||null,title,problem_statement:$('#proj-problem').value.trim(),solution_summary:$('#proj-summary').value.trim(),repo_url:$('#proj-repo').value.trim(),live_url:$('#proj-live').value.trim()}});const file=$('#proj-file').files[0];if(file){const fd=new FormData();fd.append('file',file);await api(`/submissions/${created.id}/documents?kind=prd`,{method:'POST',body:fd})}if(created.repo_url||created.live_url)await api(`/submissions/${created.id}/validate-links`,{method:'POST'});closeModal();await enterWorkspace();toast('Submission draft saved and links checked')}catch(err){toast(err.message)}})}
async function saveParticipantDraft(submit=false){const team_id=$('#participant-team')?.value;if(!team_id){toast('Create or join a team before saving a project');return}const body={track_id:$('#participant-track')?.value||null,title:$('#participant-title')?.value.trim()||'',problem_statement:$('#participant-problem')?.value.trim()||'',solution_summary:$('#participant-summary')?.value.trim()||'',target_users:$('#participant-target-users')?.value.trim()||'',tech_stack:$('#participant-tech-stack')?.value.trim()||'',repo_url:$('#participant-repo')?.value.trim()||'',live_url:$('#participant-live')?.value.trim()||'',demo_video_url:$('#participant-demo-video')?.value.trim()||''};if(body.title.length<3){toast('Enter a project title of at least 3 characters');return}try{let existing=submissions.find(s=>s.team_id===team_id);if(existing){existing=await api(`/submissions/${existing.id}`,{method:'PATCH',body})}else{body.team_id=team_id;existing=await api('/submissions',{method:'POST',body})}const consent=Boolean($('#ai-processing-consent')?.checked);if(consent!==Boolean(existing.ai_processing_consent_at)){await api(`/submissions/${existing.id}/ai-processing-consent`,{method:'POST',body:{consent}})}if(body.repo_url||body.live_url){const links=await api(`/submissions/${existing.id}/validate-links`,{method:'POST'});if(links.repository?.status==='unavailable'||links.repository?.status==='invalid')toast('Draft saved. Check the GitHub URL before submitting.')}if(submit){if(!body.repo_url){toast('Add a GitHub repository before final submission');return}const links=await api(`/submissions/${existing.id}/validate-links`,{method:'POST'});if(links.repository?.status!=='accessible'){toast('GitHub repository must be reachable before submitting');return}await api(`/submissions/${existing.id}/status`,{method:'PATCH',body:{status:'submitted'}})}await enterWorkspace();go('participant');toast(submit?'Project submitted for review':'Project draft saved')}catch(err){toast(err.message)}}
async function createOrJoinTeam(join=false){try{if(join){const code=$('#team-join-code')?.value.trim();if(!code){toast('Enter a team invite code');return}await api('/teams/join',{method:'POST',body:{join_code:code}})}else{const hackathon_id=$('#team-event')?.value,name=$('#new-team-name')?.value.trim();if(!hackathon_id||!name){toast('Choose an open event and enter a team name');return}await api('/teams',{method:'POST',body:{hackathon_id,name}})}await enterWorkspace();go('participant');toast(join?'Joined the team':'Team created. Share the invite code with your teammates')}catch(err){toast(err.message)}}
async function uploadParticipantDocument(){const file=$('#participant-file')?.files[0],team_id=$('#participant-team')?.value;if(!file||!team_id){toast('Choose a file and team');return}try{let sub=submissions.find(s=>s.team_id===team_id);if(!sub){toast('Save a project draft before uploading documents');return}const fd=new FormData();fd.append('file',file);await api(`/submissions/${sub.id}/documents?kind=${encodeURIComponent($('#document-kind').value)}`,{method:'POST',body:fd});await enterWorkspace();go('participant');toast('Document uploaded to private storage')}catch(err){toast(err.message)}}
document.addEventListener('click',e=>{
 const authMode=e.target.closest('[data-auth-mode]');if(authMode){showAuth(authMode.dataset.authMode);return}
 const eventStatus=e.target.closest('[data-event-status]');if(eventStatus){api(`/hackathons/${eventStatus.dataset.eventStatus}/status`,{method:'PATCH',body:{status:eventStatus.dataset.nextStatus}}).then(()=>enterWorkspace()).then(()=>toast('Hackathon status updated')).catch(err=>toast(err.message));return}
 const p=e.target.closest('[data-page]');if(p){e.preventDefault();go(p.dataset.page);return}
 const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();syncLiveDataView();return}
 const r=e.target.closest('[data-review]');if(r){activeId=r.dataset.review;go('judging');return}
 const sc=e.target.closest('[data-score]');if(sc){let c=rubric[+sc.dataset.score];c.score=Math.max(0,Math.min(10,c.score+(+sc.dataset.delta)));render();return}
 const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
 if(a==='logout'){localStorage.removeItem('judgex-token');localStorage.removeItem('judgex-user');currentUser=null;apiReady=false;showAuth();return}
 if(a==='new-event'){createEvent();return}if(a==='new-submission'){createSubmission();return}if(a==='export'){exportCsv();return}
 if(a==='create-team'){createOrJoinTeam(false);return}if(a==='join-team'){createOrJoinTeam(true);return}if(a==='upload-document'){uploadParticipantDocument();return}
 if(a==='pitch-start'){startPitch();return}if(a==='pitch-screen'){sharePitchScreen();return}if(a==='pitch-stop'){stopPitch();return}
 if(a==='save-submission'){saveParticipantDraft(false);return}if(a==='submit-final'){saveParticipantDraft(true);return}
 if(a==='approve'){approve();return}if(a==='close'){closeModal();return}
 if(a==='save-rubric'){weights();let n=rubric.reduce((x,c)=>x+c.weight,0);if(n!==100){toast(`Rubric weights total ${n}%. Adjust them to 100%.`);return}save();toast('Rubric saved · changes added to audit log');return}
 if(a==='reset-rubric'){rubric=defaults.map(([name,weight,score,evidence,source])=>({name,weight,score,evidence,source,desc:'Evidence-supported assessment against this criterion.',confidence:'High confidence'}));save();render();toast('Default rubric restored');return}
 if(a==='add-criterion'){rubric.push({name:'New criterion',weight:0,score:5,desc:'Describe what judges should evaluate.',evidence:'Evidence has not been added yet.',source:'Evidence required',confidence:'Low confidence'});render();toast('Criterion added. Set its weight and save.');return}
 if(a==='publish'){let n=submissions.filter(x=>!x.reviewed).length;toast(n?`${n} scorecards still need judge approval`:'Results marked ready to publish');return}
 if(a==='discussion'){toast('Project marked for judge discussion');return}
 if(a==='clarify'){modal('Request team clarification','<p class="muted" style="font-size:10px;line-height:1.6">Ask the team a focused question about their submission. This draft is saved in the local prototype only.</p><div class="form-field"><label>Question for the team</label><textarea id="clarification" placeholder="Could you share evidence for…"></textarea></div>','Save request',()=>{if(!$('#clarification').value.trim()){toast('Write a question before sending');return}closeModal();toast('Clarification request saved to the review record')});return}
 if(a==='transcript'){modal('Pitch transcript · AgriLens','<div class="evidence"><p>“We built this for a farmer who may not have an agronomist nearby or reliable internet.”</p><small>01:08 · Problem framing</small></div><div class="evidence"><p>“The user takes a photo, gets the likely disease, and sees treatment steps.”</p><small>02:16 · Demo walkthrough</small></div><div class="evidence"><p>“Our model can detect twelve common crop diseases from a single leaf image.”</p><small>03:14 · Product claim</small></div><div class="evidence"><p>“The model was trained on ten thousand field images.”</p><small>03:51 · Verify dataset claim</small></div>','Done',closeModal);return}
 if(a==='save-settings'){toast('Review settings saved in this session');return}if(a==='notifications'){toast('You’re all caught up');return}if(a==='help'){modal('JudgeX quick start','<div class="activity-item"><span class="activity-icon">1</span><div><p><b>Create an event</b></p><small>Set tracks, deadlines, and team requirements.</small></div></div><div class="activity-item"><span class="activity-icon">2</span><div><p><b>Set your judging rubric</b></p><small>Configure weighted criteria that add to 100%.</small></div></div><div class="activity-item"><span class="activity-icon">3</span><div><p><b>Collect submissions and review evidence</b></p><small>Fix evidence gaps early and invite judges.</small></div></div><div class="activity-item"><span class="activity-icon">4</span><div><p><b>Approve scorecards and publish</b></p><small>Human approval is required before results are final.</small></div></div>','Got it',closeModal);return}if(a==='audit'){toast('Audit history is available in each scorecard')}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;let pos=e.target.selectionStart;render();syncLiveDataView();let n=$('#search');n?.focus();n?.setSelectionRange(pos,pos)}if(e.target.matches('[data-weight]'))weights()});
document.addEventListener('change',e=>{if(e.target.id==='event-filter'){let f=e.target.value,list=events.filter(x=>f==='All events'||x.status===f);$('#events-list').innerHTML=list.map(x=>`<div class="event-row"><div class="event-logo">${esc(x.initials)}</div><div class="event-info"><b>${esc(x.name)}</b><small>${esc(x.category)} · ${esc(x.date)}</small></div><span class="status ${x.status==='Draft'?'draft':x.status==='Live'?'':'review'}">${esc(x.status)}</span><div class="event-progress"><small>${x.reviewed}/${x.teams||'—'} reviewed</small><div class="progress"><i style="width:${x.teams?x.reviewed/x.teams*100:0}%"></i></div></div></div>`).join('')||'<div class="empty-note">No events in this status.</div>'}if(e.target.id==='participant-team'){const t=teams.find(x=>x.id===e.target.value),s=submissions.find(x=>x.team_id===e.target.value);if($('#participant-team-name'))$('#participant-team-name').value=t?.name||'';if($('#participant-title'))$('#participant-title').value=s?.title||'';if($('#participant-problem'))$('#participant-problem').value=s?.problem_statement||'';if($('#participant-summary'))$('#participant-summary').value=s?.solution_summary||'';if($('#participant-repo'))$('#participant-repo').value=s?.repo||'';if($('#participant-live'))$('#participant-live').value=s?.live_url||'';const event=events.find(x=>x.id===t?.hackathon_id),track=$('#participant-track');if(track){track.innerHTML='<option value="">Choose a track</option>'+(event?.trackData||[]).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');track.value=s?.track_id||''}syncLiveDataView()}});
$('#navigation').addEventListener('click',e=>{let p=e.target.closest('[data-page]');if(p)go(p.dataset.page)});
$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
render();

// Live review surface backed by the consent-aware scorecard API.
let activeScorecard = null;
let activePitchSessions = [];
let activeLeaderboard = null;
let assignedJudges = [];
let activeRound = Math.min(10, Math.max(1, Number(localStorage.getItem('judgex-active-round')) || 1));
const previousGo = go;
go = function(nextPage) {
  previousGo(nextPage);
  if (nextPage === 'judging' && apiReady) loadLiveScorecard();
  if (nextPage === 'rubric' && apiReady) loadLiveRubric();
  if (nextPage === 'leaderboard' && apiReady) loadLiveLeaderboard();
};
async function loadLiveLeaderboard() {
  const event = selectedEvent();
  activeLeaderboard = null;
  if (event) {
    try { activeLeaderboard = await api(`/hackathons/${encodeURIComponent(event.id)}/leaderboard?round_number=${activeRound}`); }
    catch (err) { activeLeaderboard = {error:err.message, hackathon_id:event.id, results:[]}; }
  }
  if (page === 'leaderboard') render();
}
async function loadLiveRubric() {
  const event = selectedEvent();
  if (!event) return;
  try {
    const saved = await api(`/hackathons/${encodeURIComponent(event.id)}/rubric?round_number=${activeRound}`);
    assignedJudges = currentUser?.role === 'organizer' ? await api(`/hackathons/${encodeURIComponent(event.id)}/judges`).catch(()=>[]) : [];
    rubric = saved.criteria.map(c => ({name:c.name,weight:c.weight,score:5,evidence:c.evidence_requirements,source:c.evidence_requirements,desc:c.description,criterionId:c.id}));
    render();
    $('#app .auth-api-note')?.remove();
    const headingNode = $('#app .panel-head p');
    if (headingNode) headingNode.textContent = `${saved.name} · Version ${saved.version} · Active event rubric`;
  } catch (err) { toast(err.message); }
}
async function loadLiveScorecard() {
  const submission = scopedSubmissions().find(x => x.id === activeId) || scopedSubmissions().find(x => x.status === 'Ready for review') || scopedSubmissions()[0];
  if (!submission) return;
  activeId = submission.id;
  activeScorecard = null;
  activePitchSessions = [];
  try {
    const cards = await api(`/submissions/${encodeURIComponent(submission.id)}/scorecards`);
    activeScorecard = cards.find(card => Number(card.round_number || 1) === activeRound) || null;
  } catch { activeScorecard = null; }
  activePitchSessions = await api(`/submissions/${encodeURIComponent(submission.id)}/pitch-sessions`).catch(()=>[]);
  if (page === 'judging') render();
}
judgingPage = function() {
  const s = scopedSubmissions().find(x => x.id === activeId) || scopedSubmissions().find(x => x.status === 'Ready for review') || scopedSubmissions()[0];
  if (!s) return '<div class="empty-note">No projects to review yet.</div>';
  activeId = s.id;
  const card = activeScorecard?.submission_id === s.id ? activeScorecard : null;
  const pitchSession = activePitchSessions[0] || null;
  const criteria = card?.criteria || [];
  const score = card?.final_score ?? card?.ai_score;
  return `${heading('HUMAN-IN-THE-LOOP REVIEW','Judge workspace','Review actual submission evidence, then approve or override the recommendation.')}<section class="panel" style="padding:12px 15px;margin-bottom:14px"><label class="form-field">Judging round<select data-round-picker>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${activeRound===i+1?'selected':''}>Round ${i+1}</option>`).join('')}</select></label></section>
    <div class="review-layout"><section class="review-card"><div class="review-top"><div class="review-project"><div class="project-symbol" style="width:36px;height:36px">${esc(s.initials)}</div><div><h2>${esc(s.title)}</h2><p>${esc(s.team)} · ${esc(s.track)} · ${esc(s.id)}</p></div></div><span class="status ${card?.status==='approved'?'':'review'}">${card?esc(card.status.replace('_',' ')):'Not evaluated'}</span></div>
    <div class="review-body"><h3 class="section-title">Project summary</h3><p class="summary">${esc(s.solution_summary||'No solution summary provided.')}</p><p class="muted">${esc(s.problem_statement||'No problem statement provided.')}</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><button class="btn" data-action="ingest-evidence" data-submission="${esc(s.id)}">Ingest project evidence</button><button class="btn btn-primary" data-action="ai-evaluate" data-submission="${esc(s.id)}">Generate evidence based AI review</button><button class="btn" data-action="integrity-check" data-submission="${esc(s.id)}">Check document overlap</button><button class="btn" data-action="create-review-flag" data-kind="clarification" data-submission="${esc(s.id)}">Request clarification</button><button class="btn" data-action="create-review-flag" data-kind="discussion" data-submission="${esc(s.id)}">Flag discussion</button><button class="btn" data-action="create-review-flag" data-kind="integrity" data-submission="${esc(s.id)}">Escalate integrity concern</button></div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin:17px 0 8px"><h3 class="section-title" style="margin:0">Criterion scorecard</h3><span class="status">${criteria.length} criteria · cited evidence</span></div>
    ${card?criteria.map(c=>`<div class="criterion-row"><div class="criterion-head"><b>${esc(c.name)} <small class="muted">${c.weight}%</small></b><span>${Number(c.score).toFixed(1)} / ${c.max_score}</span></div><p class="muted">${esc(c.rationale||'No rationale returned.')}</p><div class="evidence-list">${(c.evidence||[]).map(e=>`<div class="evidence"><p>${esc(e.excerpt)}</p><small>${esc(e.source_type)} · ${esc(e.source_ref)}</small></div>`).join('')||'<p class="muted">No evidence citation returned. Treat this as unsupported.</p>'}</div><label class="form-field">Judge score<input type="number" min="0" max="${c.max_score}" step="0.1" value="${c.judge_score??c.score}" data-judge-score="${esc(c.id)}"></label><label class="form-field">Judge note<input type="text" data-judge-comment="${esc(c.id)}" value="${esc(c.human_comment||'')}" placeholder="Reason for override (optional)"></label></div>`).join(''):'<div class="empty-note">No scorecard yet. Ingest consented project materials, then generate an AI recommendation. A configured provider key is required.</div>'}
    </div><div class="review-actions"><span class="score">${score==null?'—':Number(score).toFixed(1)}<span class="muted"> / 100</span></span>${currentUser?.role==='judge'?`<button class="btn btn-primary" data-action="judge-approve" data-submission="${esc(s.id)}" ${!card||card.status==='approved'?'disabled':''}>Approve judge score</button>`:''}</div></section>
    <aside class="review-side"><section class="panel side-panel"><div class="panel-head"><div><h3>Pitch and demo evidence</h3><p>Recorded material for human review</p></div></div>${pitchSession?`<div class="event-row"><div class="event-info"><b>Pitch ${esc(pitchSession.transcription_status)} · ${pitchSession.duration_seconds}s</b><small>${pitchSession.demo_signals?.screen_share_detected?`Screen share captured for ${pitchSession.demo_signals.screen_share_seconds}s · review context only`:'No screen share signal recorded'}</small></div><button class="quiet-link" data-action="download-pitch-recording" data-session="${esc(pitchSession.id)}">Download recording</button></div>${pitchSession.claims?.length?`<h4>Quoted pitch claims</h4>${pitchSession.claims.map(c=>`<div class="event-row"><div class="event-info"><b>${esc(c.kind)} · ${esc(c.text)}</b><small>“${esc(c.quote)}”</small></div></div>`).join('')}`:''}`:'<p class="muted">No pitch recording has been uploaded.</p>'}</section><section class="panel side-panel"><div class="panel-head"><div><h3>Submission checks</h3><p>Current saved data</p></div></div><div class="integrity-row"><span>•</span><div><b>Repository</b><small>${esc(s.repo||'Not provided')}</small></div></div><div class="integrity-row"><span>•</span><div><b>Live demo</b><small>${esc(s.live_url||'Not provided')}</small></div></div><div class="integrity-row"><span>•</span><div><b>AI processing consent</b><small>${s.ai_processing_consent_at?'Recorded':'Not recorded'}</small></div></div></section><section class="panel side-panel"><div class="panel-head"><div><h3>Review process</h3><p>Evidence first, human decision final</p></div></div><p class="muted">The evaluator only receives consented materials already ingested for this submission. Its scores remain recommendations until a judge approves them.</p></section></aside></div>`;
};
leaderboard = function() {
  const event = selectedEvent();
  const published = (event?.published_rounds||[]).includes(activeRound);
  const results = activeLeaderboard?.results || [];
  const publishControl = ['organizer','super_admin'].includes(currentUser?.role) && event && !published
    ? `<button class="btn btn-primary" data-action="publish-results" data-event="${esc(event.id)}" data-round="${activeRound}">Publish Round ${activeRound} results</button>` : '';
  return `${heading('RESULTS & REPORTING','Leaderboard',published?'Judge approved results for this hackathon.':'Results appear after all submitted projects have approved scorecards.',publishControl)}
    <div class="leader-head"><div><h2>${esc(event?.name||'No event selected')}</h2><p>${published?'Published results':'Not published'} · Round ${activeRound}</p></div><span class="status ${published?'':'review'}">${published?'Published':'Draft results'}</span><label class="form-field">Round<select data-round-picker>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${activeRound===i+1?'selected':''}>Round ${i+1}</option>`).join('')}</select></label></div>
    ${activeLeaderboard?.error?`<div class="auth-api-note">${esc(activeLeaderboard.error)}</div>`:''}
    <section class="table-card"><div class="panel-head" style="padding:15px;margin:0"><div><h3>Project results</h3><p>Only judge-approved scores appear here.</p></div><button class="btn" data-action="export">⇩ Export CSV</button></div>
    ${results.length?`<table class="data-table"><thead><tr><th>Rank</th><th>Project / team</th><th>Track</th><th>Final score</th></tr></thead><tbody>${results.map(r=>`<tr><td>${String(r.rank).padStart(2,'0')}</td><td><div class="project-cell"><div class="project-symbol">${r.rank}</div><div><b>${esc(r.project_title)}</b><small>${esc(r.team_name)}</small></div></div></td><td>${esc(events.find(e=>e.id===activeLeaderboard.hackathon_id)?.trackData?.find(t=>t.id===r.track_id)?.name||'—')} ${r.track_rank===1?'<span class="status">Track winner</span>':''}</td><td><span class="score">${Number(r.score).toFixed(2)} / 100</span></td></tr>`).join('')}</tbody></table>`:'<div class="empty-note">No published leaderboard data is available yet.</div>'}</section>`;
};
const baseRubricPage = rubricPage;
rubricPage = function() {
  const event = selectedEvent();
  const roundPicker = `<section class="panel" style="padding:12px 15px;margin:0 0 14px"><label class="form-field">Judging round<select data-round-picker>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${activeRound===i+1?'selected':''}>Round ${i+1}</option>`).join('')}</select></label><small class="muted">Rubrics and scorecards are stored separately for each round.</small></section>`;
  const assignmentPanel = currentUser?.role === 'organizer' ? `<section class="panel" style="margin:0 0 14px;padding:15px"><div class="panel-head"><div><h3>Judge assignments</h3><p>Assign active judge accounts from this event's institution.</p></div></div><div class="form-grid"><div class="form-field"><label>Judge email addresses</label><input id="judge-emails" type="text" placeholder="judge1@university.edu, judge2@university.edu"></div><div class="form-field" style="align-self:end"><button class="btn btn-primary" data-action="assign-judges" data-event="${esc(event?.id||'')}">Assign judges</button></div></div>${assignedJudges.map(j=>`<div class="event-row"><div class="event-info"><b>${esc(j.name)}</b><small>${esc(j.email)}</small></div><button class="quiet-link" data-action="remove-judge" data-event="${esc(event?.id||'')}" data-judge="${esc(j.id)}">Remove</button></div>`).join('')||'<p class="muted">No judges assigned yet.</p>'}</section>` : '';
  return roundPicker + assignmentPanel + baseRubricPage().replace('Northstar Innovation Sprint · Round 1',`${esc(event?.name||'Select a hackathon')} · Round ${activeRound}`).replace('Default rubric · Version 1.0 · Changes are recorded in the audit log','Event-specific rubric · saved as an immutable version');
};
document.addEventListener('click', async e => {
  const removeJudge=e.target.closest('[data-action="remove-judge"]');if(removeJudge){try{await api(`/hackathons/${encodeURIComponent(removeJudge.dataset.event)}/judges/${encodeURIComponent(removeJudge.dataset.judge)}`,{method:'DELETE'});await loadLiveRubric();toast('Judge assignment removed');}catch(err){toast(err.message);}return;}
  const pitchDownload=e.target.closest('[data-action="download-pitch-recording"]');if(pitchDownload){try{const token=localStorage.getItem('judgex-token');const response=await fetch(`${API}/pitch-sessions/${encodeURIComponent(pitchDownload.dataset.session)}/recording`,{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!response.ok)throw new Error(`Recording download failed (${response.status})`);const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`judgex-pitch-${pitchDownload.dataset.session}.webm`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(err){toast(err.message);}return;}
  const assignButton = e.target.closest('[data-action="assign-judges"]');
  if (assignButton) {
    const emails = ($('#judge-emails')?.value||'').split(/[;,\s]+/).map(x=>x.trim()).filter(Boolean);
    if (!emails.length) { toast('Enter at least one judge email address'); return; }
    assignButton.disabled = true;
    try {
      const result = await api(`/hackathons/${encodeURIComponent(assignButton.dataset.event)}/judges`, {method:'POST',body:{judge_emails:emails}});
      toast(`Assigned ${result.judges.length} judge(s)`);
      $('#judge-emails').value = '';
    } catch (err) { toast(err.message); }
    finally { assignButton.disabled = false; }
    return;
  }
  const publishButton = e.target.closest('[data-action="publish-results"]');
  if (publishButton) {
    publishButton.disabled = true;
    try {
      await api(`/hackathons/${encodeURIComponent(publishButton.dataset.event)}/status`, {method:'PATCH',body:{status:'published',round_number:Number(publishButton.dataset.round)}});
      await enterWorkspace();
      go('leaderboard');
      toast(`Round ${publishButton.dataset.round} results published`);
    } catch (err) { toast(err.message); publishButton.disabled = false; }
    return;
  }
  const saveRubric = e.target.closest('[data-action="save-rubric"]');
  if (saveRubric && apiReady && currentUser?.role === 'organizer') {
    const event = selectedEvent();
    if (!event) return;
    const total = rubric.reduce((sum, c) => sum + Number(c.weight), 0);
    if (Math.abs(total - 100) > 0.001) return;
    try {
      const saved = await api(`/hackathons/${encodeURIComponent(event.id)}/rubric`, {method:'PUT',body:{name:`${event.name} Round ${activeRound} rubric`,round_number:activeRound,criteria:rubric.map((c,i)=>({name:c.name,description:c.desc||'',weight:Number(c.weight),max_score:10,evidence_requirements:c.evidence||'',ai_prompt:'Score only from cited project evidence. Flag low confidence or unsupported claims for human review.'}))}});
      rubric = saved.criteria.map(c => ({name:c.name,weight:c.weight,score:5,evidence:c.evidence_requirements,source:c.evidence_requirements,desc:c.description,criterionId:c.id}));
      toast(`Saved persistent rubric version ${saved.version}`);
    } catch (err) { toast(err.message); }
    return;
  }
  const button = e.target.closest('[data-action="ingest-evidence"],[data-action="ai-evaluate"],[data-action="judge-approve"],[data-action="integrity-check"]');
  if (!button) return;
  const submissionId = button.dataset.submission;
  button.disabled = true;
  try {
    if (button.dataset.action === 'ingest-evidence') {
      const result = await api(`/submissions/${encodeURIComponent(submissionId)}/ingest`, {method:'POST'});
      toast(`Indexed ${result.chunks} evidence excerpts from ${result.sources.length} sources`);
    } else if (button.dataset.action === 'integrity-check') {
      const result = await api(`/submissions/${encodeURIComponent(submissionId)}/integrity-check`, {method:'POST'});
      const overlapBody=`<p class="muted">${esc(result.message)}</p>`+(result.findings.length?result.findings.map(f=>`<div class="event-row"><div class="event-info"><b>${esc(f.project_title)} · ${f.similarity_percent}% overlap</b><small>${esc(f.current_source)} compared with ${esc(f.comparison_source)}</small></div></div>`).join(''):`<p class="muted">No likely document overlap was found.</p>`);
      modal('Documentation overlap review',overlapBody,'Done',closeModal);
    } else if (button.dataset.action === 'ai-evaluate') {
      activeScorecard = await api(`/submissions/${encodeURIComponent(submissionId)}/evaluate?round_number=${activeRound}`, {method:'POST'});
      toast('Evidence grounded scorecard generated. Judge approval is required.');
    } else {
      const overrides = (activeScorecard?.criteria||[]).map(c => ({criterion_score_id:c.id, judge_score:Number(document.querySelector(`[data-judge-score="${CSS.escape(c.id)}"]`)?.value??c.score), comment:document.querySelector(`[data-judge-comment="${CSS.escape(c.id)}"]`)?.value||''}));
      activeScorecard = await api(`/scorecards/${encodeURIComponent(activeScorecard.id)}/review`, {method:'POST',body:{comments:'Judge reviewed cited evidence.',criterion_scores:overrides}});
      toast('Judge-approved scorecard saved');
    }
    render();
  } catch (err) { toast(err.message); button.disabled = false; }
});

// Complete the operational screens with live, event-scoped data.
let selectedEventId = localStorage.getItem('judgex-selected-event') || '';
let allSubmissions = [];
let eventDashboard = null;
let eventAppeals = [];
let participantAppeals = [];
function selectedEvent() { return events.find(x => x.id === selectedEventId) || events.find(x => x.id) || null; }
function mapApiSubmission(x) {
  const team = teams.find(t => t.id === x.team_id);
  return {id:x.id,title:x.title,team:x.team_name||x.team_id.slice(0,8),team_id:x.team_id,hackathon_id:team?.hackathon_id,
    track:x.track_name||'Open Innovation',track_id:x.track_id,status:x.status==='submitted'?'Ready for review':'Draft',score:0,initials:(x.team_name||'J').split(/\s+/).map(y=>y[0]).join('').slice(0,2).toUpperCase(),
    reviewed:false,repo:x.repo_url,live_url:x.live_url,problem_statement:x.problem_statement,solution_summary:x.solution_summary,target_users:x.target_users,
    tech_stack:x.tech_stack,documents:x.documents||[],ai_processing_consent_at:x.ai_processing_consent_at,repo_check_status:x.repo_check_status,live_check_status:x.live_check_status,demo_check_status:x.demo_check_status,demo_video_url:x.demo_video_url};
}
function scopedSubmissions() { const event=selectedEvent(); return event?allSubmissions.filter(s=>s.hackathon_id===event.id):allSubmissions; }
async function loadSelectedEventData() {
  const event=selectedEvent();
  eventDashboard=null; eventAppeals=[];
  if(!event||!apiReady) return;
  try { const detail=await api(`/hackathons/${encodeURIComponent(event.id)}`);Object.assign(event,detail,{name:detail.title,category:detail.tracks?.map(t=>t.name).join(' · ')||'Open Innovation',trackData:detail.tracks||[],status:detail.status==='registration_open'?'Registration open':detail.status[0].toUpperCase()+detail.status.slice(1)}); } catch {}
  try { eventDashboard=await api(`/hackathons/${encodeURIComponent(event.id)}/dashboard`); } catch { eventDashboard=null; }
  try {
    const records=await api(`/submissions?event_id=${encodeURIComponent(event.id)}`);
    allSubmissions=records.map(mapApiSubmission);
    await Promise.all(allSubmissions.map(async s=>{
      try { const cards=await api(`/submissions/${encodeURIComponent(s.id)}/scorecards`); const card=cards[0]; if(card){s.reviewed=card.status==='approved';s.score=card.final_score??card.ai_score??0;s.scorecard_id=card.id;} } catch {}
    }));
  } catch (err) { toast(err.message); }
  if(currentUser?.role==='organizer') {
    try { eventAppeals=await api(`/hackathons/${encodeURIComponent(event.id)}/appeals`); } catch { eventAppeals=[]; }
  }
}
function workspaceEventPicker() {
  if(!apiReady||!events.length) return;
  const top=$('.top-actions'); if(!top) return;
  let select=$('#workspace-event-picker');
  if(!select){select=document.createElement('select');select.id='workspace-event-picker';select.className='select';select.setAttribute('aria-label','Select hackathon');select.style.maxWidth='220px';select.style.marginRight='8px';top.insertBefore(select,top.firstChild);}
  const previous=select.value;
  select.innerHTML=events.filter(e=>e.id).map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('');
  select.value=events.some(e=>e.id===selectedEventId)?selectedEventId:events.find(e=>e.id)?.id||'';
  selectedEventId=select.value;
}
const baseRenderWithApi=render;
render=function(){
  if(page==='appeals'){
    const keep=page; page='overview'; baseRenderWithApi(); page=keep; $('#app').innerHTML=appealsPage();
  } else if(apiReady&&['judging','leaderboard','analytics'].includes(page)){
    const ready=apiReady; apiReady=false; baseRenderWithApi(); apiReady=ready;
  } else baseRenderWithApi();
  workspaceEventPicker();
  if(page==='participant'&&apiReady){const form=$('#app .pitch-layout>div .panel'),liveBox=[...(form?.querySelectorAll('.form-field')||[])].find(box=>box.querySelector('label')?.textContent?.trim()==='Live deployment'),selected=submissions.find(s=>s.team_id===$('#participant-team')?.value);if(liveBox&&!$('#participant-demo-video'))liveBox.insertAdjacentHTML('afterend',`<div class="form-field"><label>Demo video URL (optional)</label><input id="participant-demo-video" type="url" placeholder="https://youtu.be/…" value="${esc(selected?.demo_video_url||'')}"></div>`);}
  if(page==='participant'&&apiReady){let host=$('#app .pitch-layout>div');if(host&&!$('#participant-feedback'))host.insertAdjacentHTML('beforeend','<section class="panel" id="participant-feedback" style="margin-top:14px"><div class="panel-head"><div><h3>Results and feedback</h3><p>Published judge feedback for your project</p></div></div><div class="empty-note">Feedback appears after the organizer publishes results.</div></section>');}
};
const baseGoWithEvent=go;
go=function(nextPage){baseGoWithEvent(nextPage);if(nextPage==='appeals'&&apiReady)loadSelectedEventData().then(()=>{if(page==='appeals')render()});if(nextPage==='participant'&&apiReady)loadParticipantFeedback();};
const baseEnterWorkspace=enterWorkspace;
enterWorkspace=async function(){await baseEnterWorkspace();if(!apiReady)return;allSubmissions=[...submissions].map(s=>({...s,hackathon_id:teams.find(t=>t.id===s.team_id)?.hackathon_id}));if(!events.some(e=>e.id===selectedEventId))selectedEventId=events.find(e=>e.id)?.id||'';submissions=scopedSubmissions();await loadSelectedEventData();submissions=scopedSubmissions();render();syncLiveDataView();};
document.addEventListener('change',async e=>{
  if(e.target.matches('[data-round-picker]')){activeRound=Math.max(1,Math.min(10,Number(e.target.value)||1));localStorage.setItem('judgex-active-round',String(activeRound));activeScorecard=null;activeLeaderboard=null;if(page==='rubric')await loadLiveRubric();else if(page==='judging')await loadLiveScorecard();else if(page==='leaderboard')await loadLiveLeaderboard();return;}
  if(e.target.id!=='workspace-event-picker')return;
  selectedEventId=e.target.value;localStorage.setItem('judgex-selected-event',selectedEventId);activeScorecard=null;activeLeaderboard=null;
  submissions=scopedSubmissions();await loadSelectedEventData();submissions=scopedSubmissions();render();syncLiveDataView();
  if(page==='judging')loadLiveScorecard();if(page==='leaderboard')loadLiveLeaderboard();if(page==='rubric')loadLiveRubric();if(page==='appeals')render();if(page==='participant')loadParticipantFeedback();if(page==='events'&&['organizer','super_admin'].includes(currentUser?.role))loadEventReminders();
});
overview=function(){const ev=selectedEvent(),d=eventDashboard||{};const title=ev?.name||'Your JudgeX workspace';return `${heading(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}),`Welcome, ${esc(currentUser?.name||'')}`,`Live event overview · ${esc(title)}`,currentUser?.role==='organizer'?'<button class="btn btn-primary" data-action="new-event">＋ Create hackathon</button>':'')}<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc((ev?.status||'No event').toUpperCase())}</div><h2>${esc(title)}</h2><p>${esc(ev?.category||'Select a hackathon to see its current submissions, judging progress, and evidence status.')}</p><div class="hero-bottom"><button class="btn" data-page="judging">Open judge workspace →</button><button class="text-btn" data-page="events">Manage events ↗</button></div></div><div class="hero-art"><div class="ring"></div><div class="ring r2"></div><div class="ring r3"></div><div class="art-card"><small>JUDGE APPROVAL</small><strong>${Number(d.completion_percent||0)}<span style="font-size:10px;color:#89958f">%</span></strong><div class="scoreline">${d.approved_count||0} of ${d.submitted_count||0} submitted projects</div></div></div></section><section class="stats">${[['Teams',d.team_count||0,'Registered in this event'],['Submissions',d.submission_count||0,`${d.submitted_count||0} submitted`],['Awaiting review',d.pending_count||0,'Require judge approval'],['Flagged checks',d.flagged_count||0,'Broken or invalid links']].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div></div>`).join('')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>Hackathons</h3><p>Events you can access</p></div><button class="quiet-link" data-page="events">View all →</button></div>${eventsHtml()||'<div class="empty-note">No events available.</div>'}</section><section class="panel"><div class="panel-head"><div><h3>Current event</h3><p>Operational status</p></div></div><div class="event-row"><span class="status">${esc(ev?.status||'No event')}</span><div class="event-info"><b>${esc(d.judge_count||0)} assigned judges</b><small>${esc(d.approved_count||0)} approved · ${esc(d.pending_count||0)} pending</small></div></div><p class="muted">AI recommendations require participant consent, source citations, and a judge decision before publication.</p></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Recent submissions</h3><p>${esc(title)}</p></div><button class="quiet-link" data-page="submissions">All submissions →</button></div><table class="data-table"><thead><tr><th>Project</th><th>Track</th><th>Status</th><th>Score</th><th>Judge</th><th></th></tr></thead><tbody>${rows(submissions.slice(0,5))||'<tr><td colspan="6"><div class="empty-note">No submissions yet.</div></td></tr>'}</tbody></table></section>`;};
eventsPage=function(){return `${heading('EVENT MANAGEMENT','Hackathons','Manage the events in your workspace.',currentUser?.role==='organizer'?'<button class="btn btn-primary" data-action="new-event">＋ Create hackathon</button>':'')}<section class="stats">${[['Events',events.length,'Accessible to your account'],['Teams',eventDashboard?.team_count||0,'In selected event'],['Submissions',eventDashboard?.submission_count||0,'In selected event'],['Pending reviews',eventDashboard?.pending_count||0,'Need judge approval']].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h3>Available hackathons</h3><p>Select an event with the workspace selector above.</p></div></div>${events.map(e=>{const next=({Draft:'registration_open','Registration open':'live',Live:'judging',Judging:'completed'})[e.status];const label=({Draft:'Open registration','Registration open':'Start event',Live:'Start judging',Judging:'Complete event'})[e.status];return `<div class="event-row"><div class="event-logo">${esc(e.initials)}</div><div class="event-info"><b>${esc(e.name)}</b><small>${esc(e.category)} · ${esc(e.date)}</small></div><span class="status ${e.status==='Draft'?'draft':'review'}">${esc(e.status)}</span>${currentUser?.role==='organizer'?`<button class="quiet-link" data-action="edit-event" data-event="${esc(e.id)}">Edit details</button>${next?`<button class="quiet-link" data-event-status="${esc(e.id)}" data-next-status="${next}">${label} →</button>`:''}`:''}</div>`;}).join('')||'<div class="empty-note">No hackathons found.</div>'}</section>`;};
submissionsPage=function(){const list=submissions.filter(s=>(filter==='All'||s.status===filter)&&(`${s.title} ${s.team} ${s.id} ${s.track}`).toLowerCase().includes(query.toLowerCase()));return `${heading('PROJECT INTAKE','Submissions',`${list.length} project(s) for ${esc(selectedEvent()?.name||'the selected event')}.`,'<button class="btn" data-action="export">⇩ Export CSV</button>')}<section class="stats">${[['All submissions',list.length,'In selected event'],['Submitted',list.filter(s=>s.status==='Ready for review'||s.status==='Approved').length,'Ready for judging'],['Approved',list.filter(s=>s.reviewed).length,'Judge finalized'],['Needs attention',list.filter(s=>['unavailable','invalid'].includes(s.repo_check_status)||['unavailable','invalid'].includes(s.live_check_status)).length,'Link validation flags']].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div></div>`).join('')}</section><div class="filters">${['All','Ready for review','Approved','Needs attention','Draft'].map(x=>`<button class="filter-chip ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><section class="table-card"><div class="panel-head" style="padding:15px;margin:0"><div><h3>${esc(selectedEvent()?.name||'Submissions')}</h3><p>Submission status and judge decision</p></div><input class="search" id="search" placeholder="Search projects or teams…" value="${esc(query)}"></div><table class="data-table"><thead><tr><th>Project / team</th><th>Track</th><th>Status</th><th>Score</th><th>Judge</th><th></th></tr></thead><tbody>${list.length?rows(list):'<tr><td colspan="6"><div class="empty-note">No submissions match this event and filter.</div></td></tr>'}</tbody></table></section>`;};
analytics=function(){const d=eventDashboard||{},dist=d.score_distribution||{};return `${heading('EVENT INSIGHTS','Analytics',`Current results for ${esc(selectedEvent()?.name||'the selected event')}.`,'<button class="btn" data-action="export">⇩ Export CSV</button><button class="btn" data-action="export-pdf">Print / save PDF</button>')}<section class="stats">${[['Submitted projects',d.submitted_count||0,'In this event'],['Judge-approved',d.approved_count||0,'Finalized scorecards'],['Pending review',d.pending_count||0,'Awaiting judge decision'],['Average score',d.average_score==null?'—':`${d.average_score} / 100`,'Approved scorecards']].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">${x[2]}</div></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h3>Approved score distribution</h3><p>Count of projects in each score band</p></div></div><div class="event-row">${Object.entries(dist).map(([range,count])=>`<div class="event-info"><b>${esc(range)}</b><small>${count} project(s)</small></div>`).join('')||'<div class="empty-note">No approved scores yet.</div>'}</div></section>`;};
let privacyRequests=[];
let currentEventReminders=[];
async function loadEventReminders(){const event=selectedEvent();if(!event||!['organizer','super_admin'].includes(currentUser?.role))return;try{currentEventReminders=await api(`/hackathons/${encodeURIComponent(event.id)}/reminders`);if(page==='events')render();}catch(err){toast(err.message);}}
const eventsPageBeforeReminders=eventsPage;
eventsPage=function(){const base=eventsPageBeforeReminders();const event=selectedEvent();if(!['organizer','super_admin'].includes(currentUser?.role)||!event)return base;return base+`<section class="panel" style="padding:18px;margin-top:14px"><div class="panel-head"><div><h3>Scheduled reminders · ${esc(event.name)}</h3><p>Send event reminders to participants, judges, or both.</p></div><button class="quiet-link" data-action="load-event-reminders" data-event="${esc(event.id)}">Refresh</button></div><div class="form-grid"><div class="form-field"><label>Audience</label><select id="reminder-audience"><option value="participants">Participants</option><option value="judges">Judges</option><option value="all">Participants and judges</option></select></div><div class="form-field"><label>Send at (your local time)</label><input type="datetime-local" id="reminder-time"></div><div class="form-field"><label>Subject</label><input id="reminder-subject" maxlength="240" placeholder="Submission deadline reminder"></div><div class="form-field"><label>Message</label><textarea id="reminder-body" placeholder="Write the reminder for the selected audience."></textarea></div></div><button class="btn btn-primary" data-action="schedule-event-reminder" data-event="${esc(event.id)}">Schedule reminder</button><div>${currentEventReminders.map(r=>`<div class="event-row"><div class="event-info"><b>${esc(r.subject)} · ${esc(r.audience)}</b><small>${new Date(r.scheduled_at).toLocaleString()} · ${esc(r.status)}${r.failure_detail?` · ${esc(r.failure_detail)}`:''}</small></div>${r.status==='scheduled'?`<button class="quiet-link" data-action="cancel-event-reminder" data-event="${esc(event.id)}" data-reminder="${esc(r.id)}">Cancel</button>`:''}</div>`).join('')||'<div class="empty-note">No reminders scheduled.</div>'}</div></section>`;};
settingsPage=function(){const pending=privacyRequests.find(r=>r.status==='pending'&&r.request_type==='account_deletion');return `${heading('ACCOUNT & WORKSPACE','Settings','Update your profile and manage your personal data.')}<section class="panel" style="padding:18px"><div class="panel-head"><div><h3>Profile</h3><p>Your JudgeX account details</p></div></div><div class="form-grid"><div class="form-field"><label>Display name</label><input id="profile-name" value="${esc(currentUser?.name||'')}"></div><div class="form-field"><label>Email (managed by administrator)</label><input value="${esc(currentUser?.email||'')}" disabled></div></div><p class="muted">Role: ${esc(currentUser?.role||'')}</p><button class="btn btn-primary" data-action="save-profile">Save profile</button></section><section class="panel" style="padding:18px;margin-top:14px"><div class="panel-head"><div><h3>Personal data</h3><p>Export your data or request account deletion.</p></div></div><div class="form-grid"><div><p class="muted">Download a JSON copy of your profile, team memberships, submissions, and data available to your account.</p><button class="btn" data-action="export-personal-data">Download my data</button></div><div><p class="muted">Account deletion is recorded as a request for administrator processing. Project and judging records are retained until the request is reviewed.</p><textarea id="deletion-note" placeholder="Optional details for the administrator"></textarea><button class="btn" data-action="request-account-deletion" ${pending?'disabled':''}>${pending?'Deletion request pending':'Request account deletion'}</button></div></div>${pending?`<p class="status review">Request submitted ${new Date(pending.created_at).toLocaleString()}</p>`:''}</section><section class="panel" style="padding:18px;margin-top:14px"><h3>Privacy and AI</h3><p class="muted">AI processing is controlled per submission by participant consent. Pitch recording and processing consent are separate. Credentials are kept in the backend environment, not this browser.</p></section>`;};
let adminInstitutions=[];
settingsPage=(function(base){return function(){const admin=currentUser?.role==='super_admin'?`<section class="panel" style="padding:18px;margin-top:14px"><div class="panel-head"><div><h3>Institution administration</h3><p>Manage institution records, user roles, and account access.</p></div></div><div class="form-grid"><div class="form-field"><label>New institution</label><input id="admin-institution-name" placeholder="Institution name"></div><div style="align-self:end"><button class="btn btn-primary" data-action="admin-create-institution">Add institution</button></div></div><div class="event-row"><button class="btn" data-action="admin-load-institutions">Load institutions</button><button class="btn" data-action="admin-load-users">Load users</button><select class="select" id="admin-institution-filter"><option value="">All institutions</option>${adminInstitutions.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></div><div id="admin-institutions-list">${adminInstitutions.map(i=>`<div class="event-row"><div class="event-info"><b>${esc(i.name)}</b><small>${i.user_count} users · ${i.event_count} events</small></div></div>`).join('')}</div><div id="admin-users-list"></div></section>`:'';return base()+admin;};})(settingsPage);
const goBeforePrivacy=go;
go=function(nextPage){goBeforePrivacy(nextPage);if(nextPage==='settings'&&apiReady){api('/me/privacy-requests').then(rows=>{privacyRequests=rows;if(page==='settings')render()}).catch(err=>toast(err.message));}if(nextPage==='events'&&apiReady&&['organizer','super_admin'].includes(currentUser?.role))loadEventReminders();};
document.addEventListener('click',async e=>{
  const scheduleReminder=e.target.closest('[data-action="schedule-event-reminder"]');if(scheduleReminder){const localTime=$('#reminder-time')?.value,subject=$('#reminder-subject')?.value.trim(),body=$('#reminder-body')?.value.trim();if(!localTime||!subject||!body){toast('Complete the reminder time, subject, and message');return;}try{const scheduledAt=new Date(localTime);if(Number.isNaN(scheduledAt.getTime())||scheduledAt<=new Date()){toast('Choose a future reminder time');return;}await api(`/hackathons/${encodeURIComponent(scheduleReminder.dataset.event)}/reminders`,{method:'POST',body:{audience:$('#reminder-audience').value,subject,body,scheduled_at:scheduledAt.toISOString()}});$('#reminder-subject').value='';$('#reminder-body').value='';await loadEventReminders();toast('Reminder scheduled');}catch(err){toast(err.message);}return;}
  const refreshReminders=e.target.closest('[data-action="load-event-reminders"]');if(refreshReminders){await loadEventReminders();return;}
  const cancelReminder=e.target.closest('[data-action="cancel-event-reminder"]');if(cancelReminder){try{await api(`/hackathons/${encodeURIComponent(cancelReminder.dataset.event)}/reminders/${encodeURIComponent(cancelReminder.dataset.reminder)}`,{method:'DELETE'});await loadEventReminders();toast('Reminder cancelled');}catch(err){toast(err.message);}return;}
  const createInstitution=e.target.closest('[data-action="admin-create-institution"]');if(createInstitution){const name=$('#admin-institution-name')?.value.trim();if(!name){toast('Enter an institution name');return;}try{await api('/admin/institutions',{method:'POST',body:{name}});adminInstitutions=await api('/admin/institutions');render();toast('Institution created');}catch(err){toast(err.message);}return;}
  const loadInstitutions=e.target.closest('[data-action="admin-load-institutions"]');if(loadInstitutions){try{adminInstitutions=await api('/admin/institutions');render();}catch(err){toast(err.message);}return;}
  const loadAdminUsers=e.target.closest('[data-action="admin-load-users"]');if(loadAdminUsers){try{adminInstitutions=await api('/admin/institutions');const institutionId=$('#admin-institution-filter')?.value;const users=await api(`/admin/users${institutionId?`?institution_id=${encodeURIComponent(institutionId)}`:''}`);const host=$('#admin-users-list');if(host)host.innerHTML=users.map(u=>`<div class="event-row"><div class="event-info"><b>${esc(u.name)}</b><small>${esc(u.email)} · ${u.is_active?'Active':'Inactive'}</small></div><select class="select" id="admin-role-${esc(u.id)}">${['organizer','judge','participant','mentor','viewer'].map(role=>`<option value="${role}" ${u.role===role?'selected':''}>${role}</option>`).join('')}</select><select class="select" id="admin-user-institution-${esc(u.id)}"><option value="">No institution</option>${adminInstitutions.map(i=>`<option value="${esc(i.id)}" ${u.institution_id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select><label><input type="checkbox" id="admin-user-active-${esc(u.id)}" ${u.is_active?'checked':''}> Active</label><button class="quiet-link" data-action="admin-save-user" data-user="${esc(u.id)}">Save</button></div>`).join('')||'<div class="empty-note">No users found.</div>';}catch(err){toast(err.message);}return;}
  const saveAdminUser=e.target.closest('[data-action="admin-save-user"]');if(saveAdminUser){const userId=saveAdminUser.dataset.user;try{await api(`/admin/users/${encodeURIComponent(userId)}`,{method:'PATCH',body:{role:$(`#admin-role-${CSS.escape(userId)}`).value,institution_id:$(`#admin-user-institution-${CSS.escape(userId)}`).value||null,is_active:$(`#admin-user-active-${CSS.escape(userId)}`).checked}});toast('User access updated');}catch(err){toast(err.message);}return;}
  const saveProfile=e.target.closest('[data-action="save-profile"]');if(saveProfile){try{currentUser=await api('/auth/me',{method:'PATCH',body:{name:$('#profile-name').value.trim()}});const u=localStorage.getItem('judgex-user');if(u)localStorage.setItem('judgex-user',JSON.stringify(currentUser));toast('Profile updated');render();}catch(err){toast(err.message);}return;}
  const exportData=e.target.closest('[data-action="export-personal-data"]');if(exportData){try{const data=await api('/me/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='judgex-personal-data.json';a.click();URL.revokeObjectURL(url);toast('Personal data export downloaded');}catch(err){toast(err.message);}return;}
  const deleteRequest=e.target.closest('[data-action="request-account-deletion"]');if(deleteRequest){if(!confirm('Submit an account deletion request for administrator review?'))return;try{await api('/me/privacy-requests',{method:'POST',body:{request_type:'account_deletion',note:$('#deletion-note').value.trim()}});privacyRequests=await api('/me/privacy-requests');render();toast('Account deletion request submitted');}catch(err){toast(err.message);}return;}
});

// Bind the participant workspace to the selected event, team, and persisted submission.
function participantTeam(){return teams.find(t=>t.hackathon_id===selectedEvent()?.id)||null;}
function participantSubmission(){const team=participantTeam();return team?allSubmissions.find(s=>s.team_id===team.id)||submissions.find(s=>s.team_id===team.id)||null:null;}
function teamMembersMarkup(team){const isLeader=team?.members?.find(m=>m.id===currentUser?.id)?.role==='leader';return (team?.members||[]).map(member=>`<div class="event-row"><div class="event-info"><b>${esc(member.name)}${member.id===currentUser?.id?' (you)':''}</b><small>${esc(member.role)}</small></div>${isLeader&&member.role!=='leader'?`<button class="quiet-link" data-action="team-member-role" data-team="${esc(team.id)}" data-member="${esc(member.id)}">Make leader</button><button class="quiet-link" data-action="team-member-remove" data-team="${esc(team.id)}" data-member="${esc(member.id)}">Remove</button>`:member.id===currentUser?.id&&member.role!=='leader'?`<button class="quiet-link" data-action="team-member-remove" data-team="${esc(team.id)}" data-member="${esc(member.id)}">Leave team</button>`:''}</div>`).join('');}
const renderBeforeParticipantBinding=render;
render=function(){
  renderBeforeParticipantBinding();
  if(page!=='participant'||!apiReady)return;
  const team=participantTeam(),submission=participantSubmission(),host=$('#app .pitch-layout>div .panel');
  const subtitle=$('#app h1');if(subtitle)subtitle.textContent=submission?.title||'Your project, ready for the spotlight';
  const details=$$('#app .pitch-layout>div .panel .form-field');
  const fieldFor=label=>details.find(x=>x.querySelector('label')?.textContent.trim()===label);
  const values=[['Project title',submission?.title||''],['Team name',team?.name||''],['Problem statement',submission?.problem_statement||''],['Solution summary',submission?.solution_summary||''],['GitHub repository',submission?.repo||''],['Live deployment',submission?.live_url||'']];
  values.forEach(([label,value])=>{const input=fieldFor(label)?.querySelector('input,textarea');if(input){input.value=value;input.dataset.field=label;}});
  if(host&&!$('#participant-team-context')){
    host.insertAdjacentHTML('afterbegin',`<div id="participant-team-context" class="event-row"><div class="event-info"><b>${esc(selectedEvent()?.name||'No event selected')}</b><small>${team?`${esc(team.name)} · Invite code ${esc(team.join_code)}`:'You are not registered in a team for this event yet.'}</small></div>${team?'':`<button class="btn btn-sm" data-action="participant-create-team">Create team</button><button class="btn btn-sm" data-action="participant-join-team">Join team</button>`}</div>${team?teamMembersMarkup(team):''}`);
  } else if(host&&$('#participant-team-context')){$('#participant-team-context').innerHTML=`<div class="event-info"><b>${esc(selectedEvent()?.name||'No event selected')}</b><small>${team?`${esc(team.name)} · Invite code ${esc(team.join_code)}`:'You are not registered in a team for this event yet.'}</small></div>${team?'':`<button class="btn btn-sm" data-action="participant-create-team">Create team</button><button class="btn btn-sm" data-action="participant-join-team">Join team</button>`}${team?teamMembersMarkup(team):''}`;}
  if(host&&!$('#participant-consent'))host.insertAdjacentHTML('beforeend','<label class="consent-box"><input type="checkbox" id="participant-consent"><span>I consent to AI processing of submission documents and pitch transcript for evidence extraction and judging support. This does not authorize video appearance analysis.</span></label>');
  if($('#participant-consent'))$('#participant-consent').checked=Boolean(submission?.ai_processing_consent_at);
  const recordingNotice=$('#record-consent')?.closest('label')?.querySelector('span');if(recordingNotice)recordingNotice.textContent='I consent to the camera and microphone recording being uploaded to the private event workspace after I stop. The recording and AI processing consents are separate.';
  const recordingHint=$$('#app .pitch-layout>div .panel')[1]?.querySelector('.camera-placeholder small');if(recordingHint)recordingHint.textContent='The recording uploads privately after you stop. If upload fails, you can download a local backup.';
  if(host&&!$('#participant-document-upload'))host.insertAdjacentHTML('beforeend',`<section class="panel" id="participant-document-upload" style="margin-top:12px"><h3>Project evidence</h3><p class="muted">Upload event documents (PDF, DOCX, text, or image; maximum 25 MB each).</p><div class="form-grid"><select class="select" id="participant-document-kind">${['prd','architecture','slides','screenshot','demo_video','other'].map(k=>`<option value="${k}">${k}</option>`).join('')}</select><input id="participant-document-file" type="file" accept=".pdf,.docx,.txt,.md,.png,.jpg,.jpeg,.webp"></div><button class="btn" data-action="upload-participant-document">Upload evidence</button><div>${(submission?.documents||[]).map(d=>`<div class="event-row"><div class="event-info"><b>${esc(d.kind)}</b><small>${esc(d.filename)} · ${esc(d.status)}</small></div></div>`).join('')||'<small class="muted">No documents uploaded yet.</small>'}</div></section>`);
  const video=$('#participant-demo-video');if(video)video.value=submission?.demo_video_url||'';
  const checklist=$$('#app .pitch-layout aside .panel')[0]?.querySelector('.checklist');
  if(checklist){const docs=new Set((submission?.documents||[]).map(d=>d.kind));const requirements=selectedEvent()?.required_documents||[];const checks=[['Project details',Boolean(submission?.title&&submission?.problem_statement&&submission?.solution_summary)],['GitHub repository',Boolean(submission?.repo)],['Live deployment',Boolean(submission?.live_url)],...requirements.map(kind=>[`${kind} document`,docs.has(kind)]),['Team members',Boolean(team?.members?.length)]];checklist.innerHTML=checks.map(([label,done])=>`<div class="check-row"><span class="checkmark ${done?'':'missing'}">${done?'✓':'○'}</span><div><b>${esc(label)}</b><small>${done?'Complete':'Required by event setup or recommended for review'}</small></div></div>`).join('');const count=checks.filter(x=>x[1]).length;const text=$$('#app .pitch-layout aside .panel')[0]?.querySelector('.panel-head p');if(text)text.textContent=`${count} of ${checks.length} checklist items complete`;}
};
async function saveParticipantSubmission(finalize=false){
  const team=participantTeam();if(!team){toast('Create or join a team for this event first');return;}
  const read=label=>fieldForParticipant(label)?.querySelector('input,textarea')?.value.trim()||'';
  const title=read('Project title');if(title.length<3){toast('Project title must contain at least 3 characters');return;}
  const payload={team_id:team.id,track_id:selectedEvent()?.tracks?.[0]?.id||selectedEvent()?.trackData?.[0]?.id||null,title,problem_statement:read('Problem statement'),solution_summary:read('Solution summary'),target_users:'',tech_stack:'',repo_url:read('GitHub repository'),live_url:read('Live deployment'),demo_video_url:$('#participant-demo-video')?.value.trim()||''};
  try{
    let submission=participantSubmission();
    submission=submission?.id?await api(`/submissions/${encodeURIComponent(submission.id)}`,{method:'PATCH',body:payload}):await api('/submissions',{method:'POST',body:payload});
    await api(`/submissions/${encodeURIComponent(submission.id)}/ai-processing-consent`,{method:'POST',body:{consent:Boolean($('#participant-consent')?.checked)}});
    if(finalize){
      if(payload.repo_url){const check=await api(`/submissions/${encodeURIComponent(submission.id)}/validate-links`,{method:'POST'});if(check.repository?.status!=='accessible')throw new Error('The GitHub repository must be publicly accessible before submission.');}
      submission=await api(`/submissions/${encodeURIComponent(submission.id)}/status`,{method:'PATCH',body:{status:'submitted'}});
    }
    toast(finalize?'Project submitted for judging':'Submission saved');await enterWorkspace();
  }catch(err){toast(err.message);}
}
function fieldForParticipant(label){return $$('#app .pitch-layout>div .panel .form-field').find(x=>x.querySelector('label')?.textContent.trim()===label);}
const startPitchLocalOnly=startPitch;
startPitch=async function(){
  if(!$('#record-consent')?.checked){toast('Recording consent is required before recording');return;}
  if(!$('#participant-consent')?.checked){toast('AI processing consent is required for pitch transcription');return;}
  try{
    if(!participantSubmission())await saveParticipantSubmission(false);
    const submission=participantSubmission();if(!submission){toast('Save your project before starting the pitch');return;}
    if(!navigator.mediaDevices?.getUserMedia){toast('Camera and microphone capture need a secure browser context');return;}
    const session=await api(`/submissions/${encodeURIComponent(submission.id)}/pitch-sessions`,{method:'POST',body:{recording_consent:true,ai_processing_consent:true}});pitchSessionId=session.id;
    mediaStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});const video=$('#camera-preview');video.srcObject=mediaStream;video.style.display='block';$('#camera-placeholder').style.display='none';recordChunks=[];
    const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm';recorder=new MediaRecorder(mediaStream,{mimeType:mime});recorder.ondataavailable=ev=>{if(ev.data.size)recordChunks.push(ev.data)};
    recorder.onstop=async()=>{const blob=new Blob(recordChunks,{type:mime}),file=new File([blob],`judgex-pitch-${Date.now()}.webm`,{type:'video/webm'}),form=new FormData();form.append('file',file);try{await api(`/pitch-sessions/${encodeURIComponent(pitchSessionId)}/recording?duration_seconds=${Math.max(1,pitchSeconds)}`,{method:'POST',body:form});const transcript=await api(`/pitch-sessions/${encodeURIComponent(pitchSessionId)}/transcribe`,{method:'POST'});toast(transcript.transcription_status==='completed'?'Pitch uploaded and transcribed':'Pitch uploaded; transcription needs review');}catch(err){toast(`Recording stayed on this device; upload/transcription: ${err.message}`);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;video.srcObject=null;video.style.display='none';$('#camera-placeholder').style.display='block';$('#record-pill').style.display='none';$('#pitch-status').textContent='Recording saved';$('#pitch-status').className='status';$$('[data-action="pitch-start"],[data-action="pitch-screen"],[data-action="pitch-stop"]').forEach(b=>b.disabled=b.dataset.action!=='pitch-start');};
    recorder.start(1000);pitchSeconds=0;$('#pitch-status').textContent='Recording';$('#pitch-status').className='status review';$('#record-pill').style.display='inline-block';$$('[data-action="pitch-start"],[data-action="pitch-screen"],[data-action="pitch-stop"]').forEach(b=>b.disabled=b.dataset.action!=='pitch-screen'&&b.dataset.action!=='pitch-stop');pitchInterval=setInterval(()=>{pitchSeconds++;const m=String(Math.floor(pitchSeconds/60)).padStart(2,'0'),s=String(pitchSeconds%60).padStart(2,'0');const clock=$('#pitch-duration');if(clock)clock.textContent=m+':'+s;if(pitchSeconds>=600)stopPitch();},1000);
  }catch(err){toast(err.message||'Could not start pitch recording');}
};
document.addEventListener('click',async e=>{
  if(e.target.closest('[data-action="save-submission"]')){await saveParticipantSubmission(false);return;}
  if(e.target.closest('[data-action="submit-final"]')){await saveParticipantSubmission(true);return;}
  const upload=e.target.closest('[data-action="upload-participant-document"]');if(upload){const submission=participantSubmission(),file=$('#participant-document-file')?.files?.[0];if(!submission){toast('Save the project details before uploading documents');return;}if(!file){toast('Choose a file to upload');return;}const form=new FormData();form.append('file',file);try{await api(`/submissions/${encodeURIComponent(submission.id)}/documents?kind=${encodeURIComponent($('#participant-document-kind').value)}`,{method:'POST',body:form});toast('Evidence uploaded');render();}catch(err){toast(err.message);}return;}
  if(e.target.closest('[data-action="participant-create-team"]')){const name=prompt('Choose a team name');if(!name?.trim())return;try{await api('/teams',{method:'POST',body:{hackathon_id:selectedEvent().id,name:name.trim()}});toast('Team created');await enterWorkspace();}catch(err){toast(err.message);}return;}
  const roleButton=e.target.closest('[data-action="team-member-role"]');if(roleButton){if(!window.confirm('Transfer team leadership to this member? You will become a regular member.'))return;try{await api(`/teams/${encodeURIComponent(roleButton.dataset.team)}/members/${encodeURIComponent(roleButton.dataset.member)}`,{method:'PATCH',body:{role:'leader'}});toast('Team leadership transferred');await enterWorkspace();go('participant');}catch(err){toast(err.message);}return;}
  const removeMember=e.target.closest('[data-action="team-member-remove"]');if(removeMember){if(!window.confirm('Remove this member from the team?'))return;try{await api(`/teams/${encodeURIComponent(removeMember.dataset.team)}/members/${encodeURIComponent(removeMember.dataset.member)}`,{method:'DELETE'});toast(removeMember.dataset.member===currentUser?.id?'You left the team':'Team member removed');await enterWorkspace();go('participant');}catch(err){toast(err.message);}return;}
  if(e.target.closest('[data-action="participant-join-team"]')){const code=prompt('Enter the team join code');if(!code?.trim())return;try{await api('/teams/join',{method:'POST',body:{join_code:code.trim()}});toast('Joined the team');await enterWorkspace();}catch(err){toast(err.message);}return;}
});
const baseShowAuth=showAuth;
showAuth=function(mode='login',message=''){
  if(mode==='otp'||mode==='reset'){
    apiReady=false;$('.shell').style.display='none';const root=$('#auth-gate');root.style.display='grid';let sent=false;
    root.innerHTML=`<section class="auth-brand"><div class="auth-mark"><span class="brand-mark">J<span>×</span></span> judgex</div><div><div class="eyebrow" style="color:#b6d3c4">SECURE ACCOUNT ACCESS</div><h1>${mode==='otp'?'Sign in with an email code.':'Recover your JudgeX account.'}</h1><p>Codes expire after ten minutes and can only be used once.</p></div><div class="auth-brand-foot">JUDGEX · EVIDENCE-LED EVALUATION</div></section><section class="auth-form-wrap"><form class="auth-form" id="special-auth-form"><h2>${mode==='otp'?'Email code sign in':'Reset password'}</h2>${message?`<div class="auth-error">${esc(message)}</div>`:''}<div class="form-field"><label>Email address</label><input id="special-email" type="email" required autocomplete="email" placeholder="you@university.edu"></div><div class="form-field" id="special-code-wrap" style="display:none"><label>6-digit code</label><input id="special-code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6"></div>${mode==='reset'?'<div class="form-field" id="special-password-wrap" style="display:none"><label>New password</label><input id="special-password" type="password" minlength="10" maxlength="128"></div>':''}<button class="btn btn-primary" type="submit" id="special-auth-submit">${mode==='otp'?'Send sign-in code':'Send reset code'}</button><button class="btn" style="width:100%;margin-top:8px" type="button" data-auth-special="login">Back to password sign in</button><p class="auth-help">Email codes require SMTP settings in backend/.env.</p></form></section>`;
    $('#special-auth-form').addEventListener('submit',async ev=>{ev.preventDefault();const submit=$('#special-auth-submit'),email=$('#special-email').value.trim();submit.disabled=true;try{if(!sent){await api('/auth/otp/request',{method:'POST',body:{email,purpose:mode==='otp'?'login':'password_reset'}});sent=true;$('#special-code-wrap').style.display='';if(mode==='reset')$('#special-password-wrap').style.display='';$('#special-email').disabled=true;submit.textContent=mode==='otp'?'Verify and sign in':'Update password';toast('If the account exists, a code has been sent by email');}else if(mode==='otp'){const result=await api('/auth/otp/verify',{method:'POST',body:{email,code:$('#special-code').value.trim()}});localStorage.setItem('judgex-token',result.access_token);localStorage.setItem('judgex-user',JSON.stringify(result.user));currentUser=result.user;await enterWorkspace();}else{await api('/auth/password-reset/complete',{method:'POST',body:{email,code:$('#special-code').value.trim(),new_password:$('#special-password').value}});showAuth('login','Password updated. Sign in with your new password.');}}catch(err){toast(err.message);}finally{submit.disabled=false;}});return;
  }
  baseShowAuth(mode,message);
  if(mode==='login'){
    const tabs=$('#auth-form .auth-tabs');if(tabs&&!$('#auth-special-actions'))tabs.insertAdjacentHTML('afterend','<div id="auth-special-actions" class="form-grid" style="margin:10px 0"><button class="btn" type="button" data-auth-special="otp">Use email code</button><button class="btn" type="button" data-auth-special="reset">Forgot password?</button></div><a class="btn" data-auth-google href="/api/v1/auth/google/start" style="display:block;text-align:center;margin-bottom:10px">Continue with Google</a>');
    const googleButton=$('[data-auth-google]');if(googleButton){if(location.protocol==='file:'){googleButton.dataset.googleUnavailable='true';googleButton.textContent='Open JudgeX from the local server to sign in';}else api('/auth/google/status').then(status=>{if(!status.configured){googleButton.dataset.googleUnavailable='true';googleButton.textContent='Google sign-in setup required';googleButton.title='Set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in backend/.env, then restart JudgeX.';}}).catch(()=>{});}
    if(location.protocol==='file:'&&!$('#local-demo-preview'))$('.auth-api-note')?.insertAdjacentHTML('afterend','<button class="btn" id="local-demo-preview" type="button" style="width:100%;margin:8px 0">View sample workspace (preview)</button><p class="auth-help">Preview uses sample data only. Sign-in and saved changes require the local backend.</p>');
  }
};
