createEvent=function(){modal('Create a hackathon',`<div class="form-field"><label>Hackathon title</label><input id="event-name" required minlength="3" placeholder="e.g. Northstar Winter Build"></div><div class="form-field"><label>Description</label><textarea id="event-description" placeholder="Event goals and project brief"></textarea></div><div class="form-grid"><div class="form-field"><label>Start date</label><input id="event-start" type="date"></div><div class="form-field"><label>End date</label><input id="event-end" type="date"></div></div><div class="form-grid"><div class="form-field"><label>First track</label><input id="event-track" value="Open Innovation"></div><div class="form-field"><label>Timezone</label><input id="event-timezone" value="Asia/Kolkata"></div></div><div class="form-grid"><div class="form-field"><label>Minimum team size</label><input id="event-min-team" type="number" min="1" max="20" value="1"></div><div class="form-field"><label>Maximum team size</label><input id="event-max-team" type="number" min="1" max="20" value="4"></div></div><div class="form-field"><label>Pitch length (minutes)</label><input id="event-pitch-length" type="number" min="3" max="7" value="5"></div><div class="form-grid"><div class="form-field"><label>Registration deadline</label><input id="event-registration-deadline" type="date"></div><div class="form-field"><label>Submission deadline</label><input id="event-submission-deadline" type="date"></div></div><div class="form-field"><label>Required documents</label><select id="event-required-docs" class="select" multiple><option value="prd">Project PRD</option><option value="architecture">Architecture diagram</option><option value="slides">Presentation slides</option><option value="screenshot">Screenshots</option><option value="demo_video">Demo video</option></select></div><label class="consent-box"><input id="event-allow-incomplete" type="checkbox"><span><b>Allow incomplete submissions:</b> let teams submit when required fields or documents are missing.</span></label>`,'Create draft',async()=>{const name=$('#event-name').value.trim();if(name.length<3){toast('Enter an event title of at least 3 characters');return;}const date=id=>$('#'+id).value?new Date($('#'+id).value+'T00:00:00').toISOString():null;const min=Number($('#event-min-team').value),max=Number($('#event-max-team').value);if(min>max){toast('Maximum team size must be at least the minimum');return;}try{await api('/hackathons',{method:'POST',body:{title:name,description:$('#event-description').value.trim(),timezone:$('#event-timezone').value.trim()||'UTC',start_date:date('event-start'),end_date:date('event-end'),team_size_min:min,team_size_max:max,pitch_duration_minutes:Number($('#event-pitch-length').value),registration_deadline:date('event-registration-deadline'),submission_deadline:date('event-submission-deadline'),allow_incomplete_submissions:$('#event-allow-incomplete').checked,required_documents:[...$('#event-required-docs').selectedOptions].map(option=>option.value),tracks:[{name:$('#event-track').value.trim()||'Open Innovation',description:''}]}});closeModal();await enterWorkspace();toast('Hackathon created with a default weighted rubric');}catch(err){toast(err.message);}});};
exportCsv=function(){const lines=[['Project ID','Project','Team','Track','Submission status','Judge score','Judge approved'],...scopedSubmissions().map(s=>[s.id,s.title,s.team,s.track,s.status,s.reviewed?s.score:'',s.reviewed?'Yes':'No'])];const csv=lines.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`judgex-${(selectedEvent()?.name||'event').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-results.csv`;a.click();URL.revokeObjectURL(a.href);toast('Event results exported as CSV');};
function appealsPage(){const rowsHtml=eventAppeals.map(a=>`<article class="panel" style="padding:15px;margin-bottom:12px"><div class="panel-head"><div><h3>Appeal ${esc(a.id.slice(0,8))}</h3><p>Scorecard ${esc(a.scorecard_id.slice(0,8))} · ${new Date(a.created_at).toLocaleString()}</p></div><span class="status ${a.status==='submitted'?'review':''}">${esc(a.status)}</span></div><p>${esc(a.reason)}</p>${a.status==='submitted'&&currentUser?.role==='organizer'?`<textarea data-appeal-resolution="${esc(a.id)}" placeholder="Enter the reasoned resolution"></textarea><div class="form-grid"><select class="select" data-appeal-status="${esc(a.id)}"><option value="upheld">Uphold original score</option><option value="adjusted">Adjust score and reopen review</option><option value="denied">Deny appeal</option></select><button class="btn btn-primary" data-action="resolve-appeal" data-appeal="${esc(a.id)}">Record resolution</button></div>`:`<p class="muted">${esc(a.resolution||'No resolution recorded yet.')}</p>`}</article>`).join('');return `${heading('RESULTS ADMINISTRATION','Appeals',`Appeals for ${esc(selectedEvent()?.name||'the selected event')}.`)}${rowsHtml||'<section class="panel"><div class="empty-note">No appeals have been submitted for this event.</div></section>'}`;}
