document.addEventListener('click',async e=>{
  const edit=e.target.closest('[data-action="edit-event"]');if(edit){async function editor(eventData){const asDate=value=>value?new Date(value).toISOString().slice(0,10):'';modal('Edit hackathon',`<div class="form-field"><label>Title</label><input id="edit-event-title" value="${esc(eventData.title)}"></div><div class="form-field"><label>Description</label><textarea id="edit-event-description">${esc(eventData.description||'')}</textarea></div><div class="form-grid"><div class="form-field"><label>Start date</label><input id="edit-event-start" type="date" value="${asDate(eventData.start_date)}"></div><div class="form-field"><label>End date</label><input id="edit-event-end" type="date" value="${asDate(eventData.end_date)}"></div></div><div class="form-grid"><div class="form-field"><label>Registration deadline</label><input id="edit-event-registration-deadline" type="date" value="${asDate(eventData.registration_deadline)}"></div><div class="form-field"><label>Submission deadline</label><input id="edit-event-submission-deadline" type="date" value="${asDate(eventData.submission_deadline)}"></div></div><div class="form-field"><label>Required documents</label><select id="edit-event-required-docs" class="select" multiple>${['prd','architecture','slides','screenshot','demo_video','other'].map(kind=>`<option value="${kind}" ${(eventData.required_documents||[]).includes(kind)?'selected':''}>${kind}</option>`).join('')}</select></div><label class="consent-box"><input id="edit-event-allow-incomplete" type="checkbox" ${eventData.allow_incomplete_submissions?'checked':''}><span><b>Allow incomplete submissions</b></span></label><div class="form-grid"><div class="form-field"><label>Minimum team size</label><input id="edit-event-min" type="number" min="1" max="20" value="${eventData.team_size_min}"></div><div class="form-field"><label>Maximum team size</label><input id="edit-event-max" type="number" min="1" max="20" value="${eventData.team_size_max}"></div></div><div class="form-field"><label>Timezone</label><input id="edit-event-timezone" value="${esc(eventData.timezone)}"></div><div class="form-grid"><div class="form-field"><label>Add track</label><input id="edit-track-name" placeholder="Track name"></div><div class="form-field"><label>&nbsp;</label><button class="btn" type="button" data-action="add-event-track" data-event="${esc(eventData.id)}">Add track</button></div></div><div>${(eventData.tracks||[]).map(t=>`<div class="event-row"><div class="event-info"><b>${esc(t.name)}</b><small>${esc(t.description||'')}</small></div><button class="quiet-link" data-action="remove-event-track" data-event="${esc(eventData.id)}" data-track="${esc(t.id)}">Remove</button></div>`).join('')}</div>`,'Save details',async()=>{const date=id=>$('#'+id).value?new Date($('#'+id).value+'T00:00:00').toISOString():null;try{await api(`/hackathons/${encodeURIComponent(eventData.id)}`,{method:'PATCH',body:{title:$('#edit-event-title').value.trim(),description:$('#edit-event-description').value.trim(),start_date:date('edit-event-start'),end_date:date('edit-event-end'),registration_deadline:date('edit-event-registration-deadline'),submission_deadline:date('edit-event-submission-deadline'),team_size_min:Number($('#edit-event-min').value),team_size_max:Number($('#edit-event-max').value),allow_incomplete_submissions:$('#edit-event-allow-incomplete').checked,required_documents:[...$('#edit-event-required-docs').selectedOptions].map(option=>option.value),timezone:$('#edit-event-timezone').value.trim()}});closeModal();await enterWorkspace();toast('Hackathon details saved');}catch(err){toast(err.message);}});}
    try{await editor(await api(`/hackathons/${encodeURIComponent(edit.dataset.event)}`));}catch(err){toast(err.message);}return;}
  const addTrack=e.target.closest('[data-action="add-event-track"]');if(addTrack){const name=$('#edit-track-name')?.value.trim();if(!name){toast('Enter a track name');return;}try{await api(`/hackathons/${encodeURIComponent(addTrack.dataset.event)}/tracks`,{method:'POST',body:{name,description:''}});closeModal();await enterWorkspace();toast('Track added. Reopen Edit details to review the updated track list.');}catch(err){toast(err.message);}return;}
  const removeTrack=e.target.closest('[data-action="remove-event-track"]');if(removeTrack){try{await api(`/hackathons/${encodeURIComponent(removeTrack.dataset.event)}/tracks/${encodeURIComponent(removeTrack.dataset.track)}`,{method:'DELETE'});toast('Track removed');closeModal();}catch(err){toast(err.message);}return;}
  const privacy=e.target.closest('[data-action="review-privacy"]');if(privacy){const note=$(`[data-privacy-note="${CSS.escape(privacy.dataset.request)}"]`)?.value.trim();if(!note||note.length<10){toast('Enter a resolution note of at least 10 characters');return;}try{await api(`/admin/privacy-requests/${encodeURIComponent(privacy.dataset.request)}`,{method:'PATCH',body:{status:privacy.dataset.status,note}});adminPrivacyRequests=await api('/admin/privacy-requests');render();toast(privacy.dataset.status==='completed'?'Account anonymized and disabled':'Deletion request denied');}catch(err){toast(err.message);}return;}
  const notification=e.target.closest('[data-action="notifications"]');if(notification){try{const items=await api('/notifications');const body=items.map(n=>`<div class="event-row"><div class="event-info"><b>${esc(n.subject)}</b><small>${esc(n.body)} · ${new Date(n.created_at).toLocaleString()} · ${esc(n.delivery_status)}</small></div>${!n.read_at?`<button class="quiet-link" data-action="mark-notification" data-notification="${esc(n.id)}">Mark read</button>`:''}</div>`).join('')||'<div class="empty-note">You have no notifications.</div>';modal('Notifications',body,'Done',closeModal);}catch(err){toast(err.message);}return;}
  const mark=e.target.closest('[data-action="mark-notification"]');if(mark){try{await api(`/notifications/${encodeURIComponent(mark.dataset.notification)}/read`,{method:'PATCH'});const items=await api('/notifications');modal('Notifications',items.map(n=>`<div class="event-row"><div class="event-info"><b>${esc(n.subject)}</b><small>${esc(n.body)} · ${new Date(n.created_at).toLocaleString()}</small></div></div>`).join('')||'<div class="empty-note">You have no notifications.</div>','Done',closeModal);}catch(err){toast(err.message);}return;}
  const resolve=e.target.closest('[data-action="resolve-appeal"]');if(resolve){const id=resolve.dataset.appeal,status=$(`[data-appeal-status="${CSS.escape(id)}"]`)?.value,resolution=$(`[data-appeal-resolution="${CSS.escape(id)}"]`)?.value.trim();if(!resolution){toast('Add a resolution note first');return;}try{await api(`/appeals/${encodeURIComponent(id)}`,{method:'PATCH',body:{status,resolution}});toast('Appeal resolution saved');await loadSelectedEventData();render();}catch(err){toast(err.message);}return;}
  const appeal=e.target.closest('[data-action="submit-appeal"]');if(appeal){modal('Request a score review','<div class="form-field"><label>Explain the review request</label><textarea id="appeal-reason" minlength="20" placeholder="Identify the score or evidence you want reviewed and explain why."></textarea></div>','Submit appeal',async()=>{const reason=$('#appeal-reason').value.trim();if(reason.length<20){toast('Please provide at least 20 characters');return;}try{await api(`/scorecards/${encodeURIComponent(appeal.dataset.scorecard)}/appeals`,{method:'POST',body:{reason}});closeModal();toast('Appeal submitted');loadParticipantFeedback();}catch(err){toast(err.message);}});return;}
  const cert=e.target.closest('[data-action="download-certificate"]');if(cert){const w=window.open('','_blank');if(!w){toast('Allow a new tab to print the certificate');return;}w.document.write(`<html><head><title>JudgeX Certificate</title><style>body{font-family:Georgia,serif;display:grid;place-items:center;height:95vh;color:#174735}.cert{border:8px double #5c8f71;padding:70px;text-align:center;width:75%}h1{font-size:42px}p{font-size:20px}</style></head><body><main class="cert"><h1>Certificate of Achievement</h1><p>This recognizes</p><h2>${esc(cert.dataset.team)}</h2><p>for presenting <b>${esc(cert.dataset.project)}</b> at JudgeX · Round ${esc(cert.dataset.round||'1')}</p><p>Final judge-approved score: ${esc(cert.dataset.score)} / 100</p></main><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();return;}
  const exp=e.target.closest('[data-action="export-pdf"]');if(exp){const w=window.open('','_blank');if(!w){toast('Allow a new tab to print this report');return;}const body=scopedSubmissions().map(s=>`<tr><td>${esc(s.title)}</td><td>${esc(s.team)}</td><td>${esc(s.track)}</td><td>${esc(s.status)}</td><td>${s.reviewed?Number(s.score).toFixed(2):'Pending'}</td></tr>`).join('');w.document.write(`<html><head><title>JudgeX ${esc(selectedEvent()?.name||'')} report</title><style>body{font:14px Arial;padding:32px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #ccc;text-align:left}</style></head><body><h1>${esc(selectedEvent()?.name||'JudgeX Report')}</h1><table><thead><tr><th>Project</th><th>Team</th><th>Track</th><th>Status</th><th>Score</th></tr></thead><tbody>${body}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();return;}
});
